{
  "name": "İnşaat ERP",
  "description": "Tikinti materialları mağazası üçün sadə, lakin güclü idarəetmə sistemi. Anbar, satış və süni intellekt dəstəkli hesabatlar."
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export enum Category {
  CEMENT = 'Sement və Qarışıqlar',
  BRICK = 'Kərpic və Blok',
  PAINT = 'Boya və Lak',
  TOOLS = 'Alətlər',
  PLUMBING = 'Santexnika',
  ELECTRIC = 'Elektrik',
  OTHER = 'Digər'
}

export interface Product {
  id: string;
  name: string;
  category: Category;
  price: number;
  cost: number; // Maya dəyəri
  stock: number;
  unit: string; // ədəd, kq, metr, və s.
}

export interface CartItem extends Product {
  quantity: number;
}

export interface Sale {
  id: string;
  date: string; // ISO string
  items: CartItem[];
  total: number;
  profit: number;
}

export interface DashboardStats {
  totalRevenue: number;
  totalProfit: number;
  lowStockCount: number;
  totalSalesCount: number;
}

import { GoogleGenAI } from "@google/genai";
import { Product, Sale } from '../types';

const getAiInstance = () => {
  const apiKey = process.env.API_KEY;
  if (!apiKey) {
    console.warn("API Key is missing for Gemini");
    return null;
  }
  return new GoogleGenAI({ apiKey });
};

export const generateBusinessInsight = async (products: Product[], recentSales: Sale[]): Promise<string> => {
  const ai = getAiInstance();
  if (!ai) return "API açarı tapılmadı. Zəhmət olmasa konfiqurasiyanı yoxlayın.";

  // Prepare a summary of data to send to the model
  const lowStockItems = products.filter(p => p.stock < 10).map(p => `${p.name} (${p.stock} ${p.unit})`).join(", ");
  const totalRevenue = recentSales.reduce((acc, s) => acc + s.total, 0);

  const prompt = `
    Sən bir tikinti materialları mağazasının ağıllı ERP məsləhətçisisən.
    Aşağıdakı məlumatlara əsasən mağaza müdirinə qısa, konkret biznes məsləhətləri və təhlil ver (Azərbaycan dilində).

    Vəziyyət:
    - Kritik az qalan mallar: ${lowStockItems || "Yoxdur"}
    - Son satışların ümumi dövriyyəsi: ${totalRevenue} AZN
    - Ümumi məhsul çeşidi sayı: ${products.length}
    - Son satış əməliyyatlarının sayı: ${recentSales.length}

    Zəhmət olmasa:
    1. Satışları artırmaq üçün nə etmək olar?
    2. Anbar vəziyyəti ilə bağlı xəbərdarlıq et.
    3. Ümumi motivasiya verici bir cümlə yaz.
    Cavabı formatlı (Markdown) şəkildə ver.
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: {
        thinkingConfig: { thinkingBudget: 0 } 
      }
    });
    return response.text || "Təhlil alına bilmədi.";
  } catch (error) {
    console.error("Gemini Error:", error);
    return "Süni intellekt hazırda cavab verə bilmir. Zəhmət olmasa bir az sonra yoxlayın.";
  }
};

import React from 'react';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer } from 'recharts';
import { DashboardStats, Sale } from '../types';
import { TrendingUp, AlertTriangle, Package, DollarSign } from 'lucide-react';

interface DashboardProps {
  stats: DashboardStats;
  sales: Sale[];
}

const StatCard: React.FC<{ title: string; value: string; icon: React.ReactNode; color: string }> = ({ title, value, icon, color }) => (
  <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-100 flex items-center justify-between">
    <div>
      <p className="text-sm text-slate-500 font-medium mb-1">{title}</p>
      <h3 className="text-2xl font-bold text-slate-800">{value}</h3>
    </div>
    <div className={`p-3 rounded-full ${color} text-white`}>
      {icon}
    </div>
  </div>
);

const Dashboard: React.FC<DashboardProps> = ({ stats, sales }) => {
  // Prepare chart data (Last 5 sales for simplicity, in a real app would be aggregated by date)
  const chartData = sales.slice(-7).map((s, index) => ({
    name: `Satış #${index + 1}`,
    amount: s.total,
    profit: s.profit
  }));

  return (
    <div className="space-y-6 animate-fade-in">
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
        <StatCard 
          title="Ümumi Gəlir" 
          value={`${stats.totalRevenue.toFixed(2)} ₼`} 
          icon={<TrendingUp size={24} />} 
          color="bg-emerald-500" 
        />
        <StatCard 
          title="Xalis Mənfəət" 
          value={`${stats.totalProfit.toFixed(2)} ₼`} 
          icon={<DollarSign size={24} />} 
          color="bg-blue-500" 
        />
        <StatCard 
          title="Azalan Məhsullar" 
          value={`${stats.lowStockCount}`} 
          icon={<AlertTriangle size={24} />} 
          color="bg-amber-500" 
        />
        <StatCard 
          title="Ümumi Satış Sayı" 
          value={`${stats.totalSalesCount}`} 
          icon={<Package size={24} />} 
          color="bg-indigo-500" 
        />
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        <div className="lg:col-span-2 bg-white p-6 rounded-xl shadow-sm border border-slate-100">
          <h3 className="text-lg font-semibold text-slate-800 mb-4">Satış Dinamikası</h3>
          <div className="h-80 w-full">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={chartData}>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#e2e8f0" />
                <XAxis dataKey="name" tick={{fontSize: 12}} stroke="#94a3b8" />
                <YAxis tick={{fontSize: 12}} stroke="#94a3b8" />
                <Tooltip 
                  contentStyle={{ backgroundColor: '#fff', borderRadius: '8px', border: '1px solid #e2e8f0' }}
                  cursor={{fill: '#f1f5f9'}}
                />
                <Bar dataKey="amount" fill="#6366f1" name="Gəlir" radius={[4, 4, 0, 0]} />
                <Bar dataKey="profit" fill="#10b981" name="Mənfəət" radius={[4, 4, 0, 0]} />
              </BarChart>
            </ResponsiveContainer>
          </div>
        </div>

        <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-100">
          <h3 className="text-lg font-semibold text-slate-800 mb-4">Son Satışlar</h3>
          <div className="space-y-4">
            {sales.slice(-5).reverse().map((sale) => (
              <div key={sale.id} className="flex items-center justify-between p-3 bg-slate-50 rounded-lg">
                <div>
                  <p className="text-sm font-medium text-slate-900">Çek #{sale.id.slice(0,6)}</p>
                  <p className="text-xs text-slate-500">{new Date(sale.date).toLocaleTimeString()}</p>
                </div>
                <span className="font-semibold text-emerald-600">+{sale.total.toFixed(2)} ₼</span>
              </div>
            ))}
            {sales.length === 0 && <p className="text-slate-400 text-sm text-center py-4">Hələ satış yoxdur.</p>}
          </div>
        </div>
      </div>
    </div>
  );
};

export default Dashboard;

import React, { useState } from 'react';
import { Product, Category } from '../types';
import { Plus, Search, Trash2, Edit2, AlertCircle } from 'lucide-react';

interface InventoryProps {
  products: Product[];
  onAddProduct: (p: Product) => void;
  onDeleteProduct: (id: string) => void;
  onUpdateProduct: (p: Product) => void; // Simplified for this demo
}

