export default Inventory;

import React, { useState } from 'react';
import { Product, CartItem, Sale } from '../types';
import { Search, ShoppingCart, Minus, Plus, Trash2, CheckCircle } from 'lucide-react';

interface POSProps {
  products: Product[];
  onCompleteSale: (sale: Sale) => void;
}

const POS: React.FC<POSProps> = ({ products, onCompleteSale }) => {
  const [cart, setCart] = useState<CartItem[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [successMsg, setSuccessMsg] = useState('');

  const addToCart = (product: Product) => {
    setCart(prev => {
      const existing = prev.find(item => item.id === product.id);
      if (existing) {
        if (existing.quantity >= product.stock) return prev; // Stock limit check
        return prev.map(item => item.id === product.id ? { ...item, quantity: item.quantity + 1 } : item);
      }
      return [...prev, { ...product, quantity: 1 }];
    });
  };

  const removeFromCart = (id: string) => {
    setCart(prev => prev.filter(item => item.id !== id));
  };

  const updateQuantity = (id: string, delta: number) => {
    setCart(prev => {
      return prev.map(item => {
        if (item.id === id) {
          const newQty = item.quantity + delta;
          if (newQty > item.stock) return item; // Cannot exceed stock
          if (newQty < 1) return item;
          return { ...item, quantity: newQty };
        }
        return item;
      });
    });
  };

  const handleCheckout = () => {
    if (cart.length === 0) return;

    const total = cart.reduce((sum, item) => sum + (item.price * item.quantity), 0);
    const totalCost = cart.reduce((sum, item) => sum + (item.cost * item.quantity), 0);

    const sale: Sale = {
      id: Date.now().toString(),
      date: new Date().toISOString(),
      items: [...cart],
      total: total,
      profit: total - totalCost
    };

    onCompleteSale(sale);
    setCart([]);
    setSuccessMsg('Satış uğurla tamamlandı!');
    setTimeout(() => setSuccessMsg(''), 3000);
  };

  const filteredProducts = products.filter(p => 
    p.name.toLowerCase().includes(searchTerm.toLowerCase()) && p.stock > 0
  );

  const cartTotal = cart.reduce((sum, item) => sum + (item.price * item.quantity), 0);

  return (
    <div className="flex flex-col lg:flex-row gap-6 h-[calc(100vh-140px)]">
      {/* Left: Product Grid */}
      <div className="flex-1 flex flex-col gap-4 bg-white rounded-xl shadow-sm border border-slate-100 p-4 h-full">
         <div className="relative">
          <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 text-slate-400" size={20} />
          <input 
            type="text" 
            placeholder="Satış üçün məhsul axtar..." 
            className="w-full pl-10 pr-4 py-3 border border-slate-200 rounded-xl focus:outline-none focus:ring-2 focus:ring-blue-500 bg-slate-50"
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
          />
        </div>

        <div className="flex-1 overflow-y-auto grid grid-cols-2 md:grid-cols-3 xl:grid-cols-4 gap-4 p-1">
          {filteredProducts.map(product => (
            <div 
              key={product.id} 
              onClick={() => addToCart(product)}
              className="bg-white border border-slate-200 rounded-xl p-4 cursor-pointer hover:border-blue-500 hover:shadow-md transition-all flex flex-col justify-between group h-32"
            >
              <div>
                <h4 className="font-semibold text-slate-800 line-clamp-2">{product.name}</h4>
                <p className="text-xs text-slate-500">{product.stock} {product.unit} qalıb</p>
              </div>
              <div className="flex justify-between items-end mt-2">
                <span className="font-bold text-blue-600">{product.price.toFixed(2)} ₼</span>
                <div className="bg-slate-100 p-1.5 rounded-full text-slate-400 group-hover:bg-blue-600 group-hover:text-white transition-colors">
                  <Plus size={16} />
                </div>
              </div>
            </div>
          ))}
          {filteredProducts.length === 0 && (
             <div className="col-span-full flex items-center justify-center text-slate-400 h-40">
               Məhsul tapılmadı.
             </div>
          )}
        </div>
      </div>

      {/* Right: Cart */}
      <div className="w-full lg:w-96 bg-white rounded-xl shadow-lg border border-slate-200 flex flex-col h-full overflow-hidden">
        <div className="p-4 bg-slate-50 border-b border-slate-100 flex justify-between items-center">
          <h2 className="font-bold text-lg text-slate-800 flex items-center gap-2">
            <ShoppingCart size={20} /> Cari Sifariş
          </h2>
          <span className="bg-blue-100 text-blue-700 px-2 py-1 rounded text-xs font-bold">
            {cart.length} növ
          </span>
        </div>

        <div className="flex-1 overflow-y-auto p-4 space-y-4">
          {cart.map(item => (
            <div key={item.id} className="flex justify-between items-center bg-white p-2 rounded-lg border border-slate-100 shadow-sm">
              <div className="flex-1">
                <h4 className="text-sm font-medium text-slate-900 line-clamp-1">{item.name}</h4>
                <div className="text-xs text-slate-500">{item.price.toFixed(2)} ₼ x {item.quantity}</div>
              </div>
              <div className="flex items-center gap-3">
                <div className="flex items-center gap-1 bg-slate-100 rounded-lg p-1">
                  <button onClick={() => updateQuantity(item.id, -1)} className="p-1 hover:bg-white rounded shadow-sm disabled:opacity-50">
                    <Minus size={14} />
                  </button>
                  <span className="w-6 text-center text-sm font-medium">{item.quantity}</span>
                  <button onClick={() => updateQuantity(item.id, 1)} className="p-1 hover:bg-white rounded shadow-sm">
                    <Plus size={14} />
                  </button>
                </div>
                <button onClick={() => removeFromCart(item.id)} className="text-red-400 hover:text-red-600">
                  <Trash2 size={18} />
                </button>
              </div>
            </div>
          ))}
          {cart.length === 0 && (
            <div className="h-full flex flex-col items-center justify-center text-slate-400 opacity-50">
              <ShoppingCart size={48} className="mb-2" />
              <p>Səbət boşdur</p>
            </div>
          )}
        </div>

        <div className="p-4 bg-slate-50 border-t border-slate-200">
          <div className="flex justify-between items-center mb-4">
            <span className="text-slate-600">Cəmi:</span>
            <span className="text-2xl font-bold text-slate-900">{cartTotal.toFixed(2)} ₼</span>
          </div>
          <button 
            onClick={handleCheckout}
            disabled={cart.length === 0}
            className={`w-full py-4 rounded-xl font-bold text-lg flex items-center justify-center gap-2 transition-all ${
              cart.length > 0 
              ? 'bg-blue-600 hover:bg-blue-700 text-white shadow-lg hover:shadow-blue-500/30' 
              : 'bg-slate-300 text-slate-500 cursor-not-allowed'
            }`}
          >
            Satışı Tamamla
          </button>
          {successMsg && (
            <div className="mt-2 text-center text-sm font-medium text-emerald-600 flex items-center justify-center gap-1 animate-pulse">
              <CheckCircle size={14} /> {successMsg}
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default POS;

import React, { useState } from 'react';
import { Product, Sale } from '../types';
import { generateBusinessInsight } from '../services/geminiService';
import { Sparkles, BrainCircuit, RefreshCw } from 'lucide-react';
import ReactMarkdown from 'react-markdown';

interface AssistantProps {
  products: Product[];
  sales: Sale[];
}

const Assistant: React.FC<AssistantProps> = ({ products, sales }) => {
  const [insight, setInsight] = useState<string>('');
  const [loading, setLoading] = useState(false);
  const [hasLoaded, setHasLoaded] = useState(false);

  const handleGenerate = async () => {
    setLoading(true);
    const result = await generateBusinessInsight(products, sales);
    setInsight(result);
    setLoading(false);
    setHasLoaded(true);
  };

