enum Tab {
  DASHBOARD = 'dashboard',
  INVENTORY = 'inventory',
  POS = 'pos',
  ASSISTANT = 'assistant'
}

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<Tab>(Tab.DASHBOARD);
  const [products, setProducts] = useState<Product[]>(INITIAL_PRODUCTS);
  const [sales, setSales] = useState<Sale[]>([]);
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);

  // Computed Stats
  const stats: DashboardStats = {
    totalRevenue: sales.reduce((acc, s) => acc + s.total, 0),
    totalProfit: sales.reduce((acc, s) => acc + s.profit, 0),
    lowStockCount: products.filter(p => p.stock < 10).length,
    totalSalesCount: sales.length,
  };

  const handleAddProduct = (product: Product) => {
    setProducts([...products, product]);
  };

  const handleDeleteProduct = (id: string) => {
    setProducts(products.filter(p => p.id !== id));
  };

  const handleUpdateProduct = (updated: Product) => {
     setProducts(products.map(p => p.id === updated.id ? updated : p));
  };

  const handleSaleComplete = (sale: Sale) => {
    // 1. Add Sale
    setSales([...sales, sale]);

    // 2. Decrease Stock
    setProducts(currentProducts => {
      return currentProducts.map(prod => {
        const soldItem = sale.items.find(item => item.id === prod.id);
        if (soldItem) {
          return { ...prod, stock: Math.max(0, prod.stock - soldItem.quantity) };
        }
        return prod;
      });
    });
  };

  const renderContent = () => {
    switch (activeTab) {
      case Tab.DASHBOARD:
        return <Dashboard stats={stats} sales={sales} />;
      case Tab.INVENTORY:
        return <Inventory products={products} onAddProduct={handleAddProduct} onDeleteProduct={handleDeleteProduct} onUpdateProduct={handleUpdateProduct} />;
      case Tab.POS:
        return <POS products={products} onCompleteSale={handleSaleComplete} />;
      case Tab.ASSISTANT:
        return <Assistant products={products} sales={sales} />;
