                <input 
                  type="text" 
                  placeholder="ədəd, kq..."
                  className="w-full border border-slate-300 p-2 rounded-lg outline-none focus:ring-2 focus:ring-blue-500"
                  value={newProduct.unit}
                  onChange={e => setNewProduct({...newProduct, unit: e.target.value})}
                />
             </div>
             <div>
                <label className="block text-sm font-medium text-slate-700 mb-1">Maya Dəyəri (₼)</label>
                <input 
                  type="number" 
                  min="0"
                  step="0.01"
                  className="w-full border border-slate-300 p-2 rounded-lg outline-none focus:ring-2 focus:ring-blue-500"
                  value={newProduct.cost}
                  onChange={e => setNewProduct({...newProduct, cost: Number(e.target.value)})}
                />
             </div>
             <div>
                <label className="block text-sm font-medium text-slate-700 mb-1">Satış Qiyməti (₼)</label>
                <input 
                  type="number" 
                  min="0"
                  step="0.01"
                  className="w-full border border-slate-300 p-2 rounded-lg outline-none focus:ring-2 focus:ring-blue-500"
                  value={newProduct.price}
                  onChange={e => setNewProduct({...newProduct, price: Number(e.target.value)})}
                />
             </div>
             <div>
                <label className="block text-sm font-medium text-slate-700 mb-1">Say</label>
                <input 
                  type="number" 
                  min="0"
                  className="w-full border border-slate-300 p-2 rounded-lg outline-none focus:ring-2 focus:ring-blue-500"
                  value={newProduct.stock}
                  onChange={e => setNewProduct({...newProduct, stock: Number(e.target.value)})}
                />
             </div>
          </div>
          <div className="flex justify-end gap-3 mt-6">
            <button 
              onClick={() => setShowForm(false)}
              className="px-6 py-2 rounded-lg border border-slate-200 text-slate-600 hover:bg-slate-50 font-medium"
            >
              Ləğv et
            </button>
            <button 
              onClick={handleSave}
              className="px-6 py-2 rounded-lg bg-emerald-600 hover:bg-emerald-700 text-white font-medium flex items-center gap-2 shadow-sm shadow-emerald-200"
            >
              <Save size={18} />
              Əlavə et
            </button>
          </div>
        </div>
      )}

      <div className="bg-white rounded-xl shadow-sm border border-slate-100 overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full text-left border-collapse">
            <thead>
              <tr className="bg-slate-50 text-slate-600 text-sm font-medium border-b border-slate-100 select-none">
                <th className="p-4 cursor-pointer hover:bg-slate-100 transition-colors" onClick={() => handleSort('name')}>
                  <div className="flex items-center gap-2">Məhsul Adı {getSortIcon('name')}</div>
                </th>
                <th className="p-4 cursor-pointer hover:bg-slate-100 transition-colors" onClick={() => handleSort('category')}>
                  <div className="flex items-center gap-2">Kateqoriya {getSortIcon('category')}</div>
                </th>
                <th className="p-4 cursor-pointer hover:bg-slate-100 transition-colors" onClick={() => handleSort('cost')}>
                   <div className="flex items-center gap-2">Alış {getSortIcon('cost')}</div>
                </th>
                <th className="p-4 cursor-pointer hover:bg-slate-100 transition-colors" onClick={() => handleSort('price')}>
                   <div className="flex items-center gap-2">Satış {getSortIcon('price')}</div>
                </th>
                <th className="p-4 cursor-pointer hover:bg-slate-100 transition-colors" onClick={() => handleSort('stock')}>
                   <div className="flex items-center gap-2">Anbar {getSortIcon('stock')}</div>
                </th>
                <th className="p-4 text-right">Əməliyyatlar</th>
              </tr>
            </thead>
            <tbody>
              {sortedProducts.map(product => (
                <tr key={product.id} className="border-b border-slate-50 hover:bg-slate-50 transition-colors">
                  <td className="p-4 font-medium text-slate-800">{product.name}</td>
                  <td className="p-4">
                    <span className="px-2 py-1 bg-slate-100 text-slate-600 text-xs rounded-full whitespace-nowrap">
                      {product.category}
                    </span>
                  </td>
                  <td className="p-4 text-slate-600">{product.cost.toFixed(2)} ₼</td>
                  <td className="p-4 font-medium text-emerald-600">{product.price.toFixed(2)} ₼</td>
                  <td className="p-4">
                    <div className={`flex items-center gap-2 ${product.stock < lowStockThreshold ? 'text-amber-600 font-bold' : 'text-slate-600'}`}>
                      {product.stock} {product.unit}
                      {product.stock < lowStockThreshold && <AlertCircle size={16} />}
                    </div>
                  </td>
                  <td className="p-4 text-right">
                    <button 
                      onClick={() => onDeleteProduct(product.id)}
                      className="text-red-500 hover:bg-red-50 p-2 rounded-lg transition-colors"
                      title="Sil"
                    >
                      <Trash2 size={18} />
                    </button>
                  </td>
                </tr>
              ))}
              {sortedProducts.length === 0 && (
                <tr>
                  <td colSpan={6} className="p-8 text-center text-slate-400">
                    Məhsul tapılmadı.
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
};

export default Inventory;

