import React, { useState, useRef } from 'react';
import { Product, Category } from '../types';
import { Plus, Search, Trash2, AlertCircle, ArrowUpDown, ArrowUp, ArrowDown, X, Save, Upload, Download, FileSpreadsheet } from 'lucide-react';

interface InventoryProps {
  products: Product[];
  onAddProduct: (p: Product) => void;
  onDeleteProduct: (id: string) => void;
  onUpdateProduct: (p: Product) => void;
  onBulkAddProducts: (products: Product[]) => void;
  lowStockThreshold: number;
}

const Inventory: React.FC<InventoryProps> = ({ products, onAddProduct, onDeleteProduct, lowStockThreshold, onBulkAddProducts }) => {
  const [showForm, setShowForm] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Sorting & Filtering State
  const [sortConfig, setSortConfig] = useState<{ key: keyof Product; direction: 'asc' | 'desc' } | null>(null);
  const [filterCategory, setFilterCategory] = useState<string>('ALL');
  const [filterStock, setFilterStock] = useState<'ALL' | 'LOW'>('ALL');

  // New Product State
  const [newProduct, setNewProduct] = useState<Partial<Product>>({
    name: '',
    category: Category.OTHER,
    price: 0,
    cost: 0,
    stock: 0,
    unit: 'ədəd'
  });

  const handleSave = () => {
    if (!newProduct.name || !newProduct.price) return;

    const product: Product = {
      id: Date.now().toString(),
      name: newProduct.name,
      category: newProduct.category as Category,
      price: Number(newProduct.price),
      cost: Number(newProduct.cost),
      stock: Number(newProduct.stock),
      unit: newProduct.unit || 'ədəd'
    };

    onAddProduct(product);
    setShowForm(false);
    setNewProduct({ name: '', category: Category.OTHER, price: 0, cost: 0, stock: 0, unit: 'ədəd' });
  };

  const handleDownloadTemplate = () => {
    const headers = "name,category,price,cost,stock,unit";
    // Using simple CSV generation. Be wary of commas in data.
    const sample = "Yeni Məhsul,Digər,10.00,8.00,50,ədəd";
    const csvContent = "data:text/csv;charset=utf-8," + headers + "\n" + sample;
    const encodedUri = encodeURI(csvContent);
    const link = document.createElement("a");
    link.setAttribute("href", encodedUri);
    link.setAttribute("download", "mehsul_sablonu.csv");
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const handleFileUpload = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (e) => {
      const text = e.target?.result as string;
      if (!text) return;

      const lines = text.split('\n');
      const parsedProducts: Product[] = [];

      // Start from index 1 to skip header
      for (let i = 1; i < lines.length; i++) {
          const line = lines[i].trim();
          if (!line) continue;

          // Simple CSV split
          const parts = line.split(',');
          // Handle potential issues if description has commas (not supported in this simple version)
          if (parts.length < 6) continue;

          const [name, category, price, cost, stock, unit] = parts;

          // Basic validation
          if (name && !isNaN(Number(price))) {
              const matchedCategory = Object.values(Category).find(c => c === category.trim()) || Category.OTHER;

              parsedProducts.push({
                  id: Date.now().toString() + Math.random().toString().slice(2, 6) + i,
                  name: name.trim(),
                  category: matchedCategory as Category,
                  price: Number(price),
                  cost: Number(cost) || 0,
                  stock: Number(stock) || 0,
                  unit: unit?.trim() || 'ədəd'
              });
          }
      }

      if (parsedProducts.length > 0) {
          onBulkAddProducts(parsedProducts);
          if (fileInputRef.current) fileInputRef.current.value = '';
          alert(`${parsedProducts.length} məhsul uğurla idxal edildi!`);
      } else {
          alert('Fayldan heç bir məhsul oxuna bilmədi. Zəhmət olmasa şablonu yoxlayın.');
      }
    };
    reader.readAsText(file);
  };

  const handleSort = (key: keyof Product) => {
    let direction: 'asc' | 'desc' = 'asc';
    if (sortConfig && sortConfig.key === key && sortConfig.direction === 'asc') {
      direction = 'desc';
    }
    setSortConfig({ key, direction });
  };

  const getSortIcon = (columnKey: keyof Product) => {
    if (sortConfig?.key !== columnKey) return <ArrowUpDown size={14} className="text-slate-300" />;
    return sortConfig.direction === 'asc' ? 
      <ArrowUp size={14} className="text-blue-600" /> : 
      <ArrowDown size={14} className="text-blue-600" />;
  };

  // Filter Logic
  const filteredProducts = products.filter(p => {
    const matchesSearch = p.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
                          p.category.toLowerCase().includes(searchTerm.toLowerCase());
    const matchesCategory = filterCategory === 'ALL' || p.category === filterCategory;
    const matchesStock = filterStock === 'ALL' || (filterStock === 'LOW' && p.stock < lowStockThreshold);

    return matchesSearch && matchesCategory && matchesStock;
  });

  // Sort Logic
  const sortedProducts = [...filteredProducts].sort((a, b) => {
    if (!sortConfig) return 0;
    const { key, direction } = sortConfig;

    if (key === 'name' || key === 'category') {
       const valA = a[key].toLowerCase();
       const valB = b[key].toLowerCase();
       if (valA < valB) return direction === 'asc' ? -1 : 1;
       if (valA > valB) return direction === 'asc' ? 1 : -1;
       return 0;
    }

    // Numeric sort
    const valA = Number(a[key as keyof Product]);
    const valB = Number(b[key as keyof Product]);
    return direction === 'asc' ? valA - valB : valB - valA;
  });

  return (
    <div className="space-y-6 animate-fade-in">
      {/* Hidden File Input */}
      <input 
        type="file" 
        ref={fileInputRef} 
        onChange={handleFileUpload} 
        className="hidden" 
        accept=".csv" 
      />

      {/* Controls Header */}
      <div className="flex flex-col xl:flex-row justify-between items-start xl:items-center gap-4 bg-white p-4 rounded-xl shadow-sm border border-slate-100">

        {/* Search */}
        <div className="relative w-full xl:w-80">
          <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 text-slate-400" size={20} />
          <input 
            type="text" 
            placeholder="Axtar..." 
            className="w-full pl-10 pr-4 py-2 border border-slate-200 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500"
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
          />
        </div>

        {/* Filters */}
        <div className="flex flex-col sm:flex-row gap-4 w-full xl:w-auto overflow-x-auto pb-2 sm:pb-0">
          <select 
            className="border border-slate-200 rounded-lg px-3 py-2 text-slate-700 focus:outline-none focus:ring-2 focus:ring-blue-500 bg-white"
            value={filterCategory}
            onChange={(e) => setFilterCategory(e.target.value)}
          >
            <option value="ALL">Bütün Kateqoriyalar</option>
            {Object.values(Category).map(c => <option key={c} value={c}>{c}</option>)}
          </select>

          <button 
            onClick={() => setFilterStock(filterStock === 'ALL' ? 'LOW' : 'ALL')}
            className={`flex items-center justify-center gap-2 px-4 py-2 rounded-lg border transition-colors whitespace-nowrap ${
              filterStock === 'LOW' 
                ? 'bg-amber-50 border-amber-200 text-amber-700 font-medium' 
                : 'bg-white border-slate-200 text-slate-600 hover:bg-slate-50'
            }`}
          >
            <AlertCircle size={18} className={filterStock === 'LOW' ? 'text-amber-600' : 'text-slate-400'} />
            {filterStock === 'LOW' ? 'Kritik Say' : 'Hamısı'}
          </button>

          {/* Import/Export Actions */}
          <div className="flex items-center gap-2 border-l pl-4 border-slate-200">
            <button 
              onClick={handleDownloadTemplate} 
              className="p-2 text-slate-500 hover:text-blue-600 hover:bg-blue-50 rounded-lg transition-colors"
              title="Şablonu yüklə"
            >
              <Download size={20} />
            </button>
            <button 
              onClick={() => fileInputRef.current?.click()} 
              className="p-2 text-slate-500 hover:text-blue-600 hover:bg-blue-50 rounded-lg transition-colors"
              title="CSV İdxal et"
            >
              <Upload size={20} />
            </button>
          </div>

          <button 
            onClick={() => setShowForm(!showForm)}
            className={`flex items-center justify-center gap-2 px-4 py-2 rounded-lg transition-colors whitespace-nowrap ${
              showForm ? 'bg-slate-100 text-slate-700' : 'bg-blue-600 hover:bg-blue-700 text-white'
            }`}
          >
            {showForm ? <X size={20} /> : <Plus size={20} />}
            <span className="hidden sm:inline">{showForm ? 'Bağla' : 'Yeni Məhsul'}</span>
            <span className="sm:hidden">{showForm ? 'Bağla' : 'Yeni'}</span>
          </button>
        </div>
      </div>

      {/* Inline Add Product Form */}
      {showForm && (
        <div className="bg-white rounded-xl shadow-sm border border-blue-200 p-6 animate-fade-in-down">
          <h3 className="text-lg font-bold text-slate-800 mb-4 flex items-center gap-2">
            <Plus className="text-blue-600" size={20} /> Yeni Məhsul Məlumatları
          </h3>
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-6 gap-4">
             <div className="xl:col-span-2">
                <label className="block text-sm font-medium text-slate-700 mb-1">Məhsul Adı</label>
                <input 
                  type="text" 
                  className="w-full border border-slate-300 p-2 rounded-lg focus:ring-2 focus:ring-blue-500 outline-none"
                  placeholder="Məs: Sement 50kq"
                  value={newProduct.name}
                  onChange={e => setNewProduct({...newProduct, name: e.target.value})}
                />
             </div>
             <div className="xl:col-span-1">
                <label className="block text-sm font-medium text-slate-700 mb-1">Kateqoriya</label>
                <select 
                  className="w-full border border-slate-300 p-2 rounded-lg outline-none focus:ring-2 focus:ring-blue-500 bg-white"
                  value={newProduct.category}
                  onChange={e => setNewProduct({...newProduct, category: e.target.value as Category})}
                >
                  {Object.values(Category).map(c => <option key={c} value={c}>{c}</option>)}
                </select>
             </div>
             <div>
                <label className="block text-sm font-medium text-slate-700 mb-1">Vahid</label>
                <input 
                  type="text" 
                  placeholder="ədəd, kq..."
                  className="w-full border border-slate-300 p-2 rounded-lg outline-none focus:ring-2 focus:ring-blue-500"
                  value={newProduct.unit}
                  onChange={e => setNewProduct({...newProduct, unit: e.target.value})}
                />
             </div>
             <div>
                <label className="block text-sm font-medium text-slate-700 mb-1">Maya Dəyəri (₼)</label>
                <input 
                  type="number" 
                  min="0"
                  step="0.01"
                  className="w-full border border-slate-300 p-2 rounded-lg outline-none focus:ring-2 focus:ring-blue-500"
                  value={newProduct.cost}
                  onChange={e => setNewProduct({...newProduct, cost: Number(e.target.value)})}
                />
             </div>
             <div>
                <label className="block text-sm font-medium text-slate-700 mb-1">Satış Qiyməti (₼)</label>
                <input 
                  type="number" 
                  min="0"
                  step="0.01"
                  className="w-full border border-slate-300 p-2 rounded-lg outline-none focus:ring-2 focus:ring-blue-500"
                  value={newProduct.price}
                  onChange={e => setNewProduct({...newProduct, price: Number(e.target.value)})}
                />
             </div>
             <div>
                <label className="block text-sm font-medium text-slate-700 mb-1">Say</label>
                <input 
                  type="number" 
                  min="0"
                  className="w-full border border-slate-300 p-2 rounded-lg outline-none focus:ring-2 focus:ring-blue-500"
                  value={newProduct.stock}
                  onChange={e => setNewProduct({...newProduct, stock: Number(e.target.value)})}
                />
             </div>
          </div>
          <div className="flex justify-end gap-3 mt-6">
            <button 
              onClick={() => setShowForm(false)}
              className="px-6 py-2 rounded-lg border border-slate-200 text-slate-600 hover:bg-slate-50 font-medium"
            >
              Ləğv et
            </button>
            <button 
              onClick={handleSave}
              className="px-6 py-2 rounded-lg bg-emerald-600 hover:bg-emerald-700 text-white font-medium flex items-center gap-2 shadow-sm shadow-emerald-200"
            >
              <Save size={18} />
              Əlavə et
            </button>
          </div>
        </div>
      )}

      <div className="bg-white rounded-xl shadow-sm border border-slate-100 overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full text-left border-collapse">
            <thead>
              <tr className="bg-slate-50 text-slate-600 text-sm font-medium border-b border-slate-100 select-none">
                <th className="p-4 cursor-pointer hover:bg-slate-100 transition-colors" onClick={() => handleSort('name')}>
                  <div className="flex items-center gap-2">Məhsul Adı {getSortIcon('name')}</div>
                </th>
                <th className="p-4 cursor-pointer hover:bg-slate-100 transition-colors" onClick={() => handleSort('category')}>
                  <div className="flex items-center gap-2">Kateqoriya {getSortIcon('category')}</div>
                </th>
                <th className="p-4 cursor-pointer hover:bg-slate-100 transition-colors" onClick={() => handleSort('cost')}>
                   <div className="flex items-center gap-2">Alış {getSortIcon('cost')}</div>
                </th>
                <th className="p-4 cursor-pointer hover:bg-slate-100 transition-colors" onClick={() => handleSort('price')}>
                   <div className="flex items-center gap-2">Satış {getSortIcon('price')}</div>
                </th>
                <th className="p-4 cursor-pointer hover:bg-slate-100 transition-colors" onClick={() => handleSort('stock')}>
                   <div className="flex items-center gap-2">Anbar {getSortIcon('stock')}</div>
                </th>
                <th className="p-4 text-right">Əməliyyatlar</th>
              </tr>
            </thead>
            <tbody>
              {sortedProducts.map(product => (
                <tr key={product.id} className="border-b border-slate-50 hover:bg-slate-50 transition-colors">
                  <td className="p-4 font-medium text-slate-800">{product.name}</td>
                  <td className="p-4">
                    <span className="px-2 py-1 bg-slate-100 text-slate-600 text-xs rounded-full whitespace-nowrap">
                      {product.category}
                    </span>
                  </td>
                  <td className="p-4 text-slate-600">{product.cost.toFixed(2)} ₼</td>
                  <td className="p-4 font-medium text-emerald-600">{product.price.toFixed(2)} ₼</td>
                  <td className="p-4">
                    <div className={`flex items-center gap-2 ${product.stock < lowStockThreshold ? 'text-amber-600 font-bold' : 'text-slate-600'}`}>
                      {product.stock} {product.unit}
                      {product.stock < lowStockThreshold && <AlertCircle size={16} />}
                    </div>
                  </td>
                  <td className="p-4 text-right">
                    <button 
                      onClick={() => onDeleteProduct(product.id)}
                      className="text-red-500 hover:bg-red-50 p-2 rounded-lg transition-colors"
                      title="Sil"
                    >
                      <Trash2 size={18} />
                    </button>
                  </td>
                </tr>
              ))}
              {sortedProducts.length === 0 && (
                <tr>
                  <td colSpan={6} className="p-8 text-center text-slate-400">
                    Məhsul tapılmadı.
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
};

export default Inventory;

import React, { useState, useEffect } from 'react';
import { LayoutDashboard, ShoppingCart, Package, Sparkles, LogOut, Menu, Settings, History } from 'lucide-react';
import { Product, Sale, DashboardStats, Category, AuditLogEntry, AuditAction } from './types';
import Dashboard from './components/Dashboard';
import Inventory from './components/Inventory';
import POS from './components/POS';
import Assistant from './components/Assistant';
import SettingsPage from './components/Settings';
import AuditLogs from './components/AuditLogs';

// Mock Data
const INITIAL_PRODUCTS: Product[] = [
  { id: '1', name: 'Norm Sement 400 (50kq)', category: Category.CEMENT, price: 8.50, cost: 6.50, stock: 150, unit: 'kisə' },
  { id: '2', name: 'Qırmızı Kərpic (İçi boş)', category: Category.BRICK, price: 0.45, cost: 0.25, stock: 5000, unit: 'ədəd' },
  { id: '3', name: 'Emusiya Ağ (25kq)', category: Category.PAINT, price: 45.00, cost: 35.00, stock: 12, unit: 'vedrə' },
  { id: '4', name: 'Lopata (Qar kürəyi)', category: Category.TOOLS, price: 12.00, cost: 8.00, stock: 8, unit: 'ədəd' },
  { id: '5', name: 'Alçıpan (Gilan)', category: Category.OTHER, price: 11.00, cost: 8.50, stock: 45, unit: 'lövhə' },
];

enum Tab {
  DASHBOARD = 'dashboard',
  INVENTORY = 'inventory',
  POS = 'pos',
  ASSISTANT = 'assistant',
  AUDIT = 'audit',
  SETTINGS = 'settings'
}

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<Tab>(Tab.DASHBOARD);
  const [products, setProducts] = useState<Product[]>(INITIAL_PRODUCTS);
  const [sales, setSales] = useState<Sale[]>([]);
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);
  const [lowStockThreshold, setLowStockThreshold] = useState<number>(10);
  const [auditLogs, setAuditLogs] = useState<AuditLogEntry[]>([]);

  // Helper to add log
  const addLog = (action: AuditAction, details: string) => {
    const newLog: AuditLogEntry = {
      id: Date.now().toString() + Math.random().toString().slice(2, 5),
      date: new Date().toISOString(),
      action,
      details
    };
    setAuditLogs(prev => [newLog, ...prev]);
  };

  // Computed Stats
  const stats: DashboardStats = {
    totalRevenue: sales.reduce((acc, s) => acc + s.total, 0),
    totalProfit: sales.reduce((acc, s) => acc + s.profit, 0),
    lowStockCount: products.filter(p => p.stock < lowStockThreshold).length,
    totalSalesCount: sales.length,
  };

  const handleAddProduct = (product: Product) => {
    setProducts([...products, product]);
    addLog(AuditAction.ADD, `${product.name} əlavə edildi. İlkin say: ${product.stock} ${product.unit}`);
  };

  const handleBulkAddProducts = (newProducts: Product[]) => {
    setProducts(prev => [...prev, ...newProducts]);
    addLog(AuditAction.BULK_IMPORT, `${newProducts.length} məhsul CSV faylından idxal edildi.`);
  };

  const handleDeleteProduct = (id: string) => {
    const p = products.find(x => x.id === id);
    if (p) {
      addLog(AuditAction.DELETE, `${p.name} silindi.`);
    }
    setProducts(products.filter(p => p.id !== id));
  };

  const handleUpdateProduct = (updated: Product) => {
     setProducts(products.map(p => p.id === updated.id ? updated : p));
     addLog(AuditAction.UPDATE, `${updated.name} məlumatları yeniləndi.`);
  };

  const handleSaleComplete = (sale: Sale) => {
    // 1. Add Sale
    setSales([...sales, sale]);

    // 2. Decrease Stock
    setProducts(currentProducts => {
      return currentProducts.map(prod => {
        const soldItem = sale.items.find(item => item.id === prod.id);
        if (soldItem) {
          return { ...prod, stock: Math.max(0, prod.stock - soldItem.quantity) };
        }
        return prod;
      });
    });

    // 3. Log
    const itemsSummary = sale.items.map(i => `${i.quantity}x ${i.name}`).join(', ');
    addLog(AuditAction.SALE, `Satış #${sale.id.slice(0,6)}: ${itemsSummary}`);
  };

  const renderContent = () => {
    switch (activeTab) {
      case Tab.DASHBOARD:
        return <Dashboard stats={stats} sales={sales} />;
      case Tab.INVENTORY:
        return <Inventory 
          products={products} 
          onAddProduct={handleAddProduct} 
          onDeleteProduct={handleDeleteProduct} 
          onUpdateProduct={handleUpdateProduct} 
          onBulkAddProducts={handleBulkAddProducts}
          lowStockThreshold={lowStockThreshold} 
        />;
      case Tab.POS:
        return <POS products={products} onCompleteSale={handleSaleComplete} />;
      case Tab.ASSISTANT:
        return <Assistant products={products} sales={sales} lowStockThreshold={lowStockThreshold} />;
      case Tab.AUDIT:
        return <AuditLogs logs={auditLogs} />;
      case Tab.SETTINGS:
        return <SettingsPage lowStockThreshold={lowStockThreshold} onUpdateThreshold={setLowStockThreshold} />;
      default:
        return <Dashboard stats={stats} sales={sales} />;
    }
  };

  const NavItem = ({ tab, label, icon: Icon }: { tab: Tab, label: string, icon: any }) => (
    <button
      onClick={() => { setActiveTab(tab); setIsMobileMenuOpen(false); }}
      className={`w-full flex items-center gap-3 px-4 py-3 rounded-lg transition-all duration-200 ${
        activeTab === tab 
          ? 'bg-blue-600 text-white shadow-lg shadow-blue-500/30 font-medium' 
          : 'text-slate-500 hover:bg-slate-100 hover:text-slate-900'
      }`}
    >
      <Icon size={20} />
      <span>{label}</span>
    </button>
  );

  return (
    <div className="flex h-screen bg-slate-50 overflow-hidden font-sans">
      {/* Sidebar - Desktop */}
      <aside className="hidden md:flex w-64 flex-col bg-white border-r border-slate-200 shadow-sm z-10">
        <div className="p-6 border-b border-slate-100">
          <div className="flex items-center gap-2 text-blue-700">
            <Package size={28} className="fill-current" />
            <span className="text-xl font-bold tracking-tight">İnşaat<span className="text-slate-800">ERP</span></span>
          </div>
        </div>

        <nav className="flex-1 p-4 space-y-2">
          <NavItem tab={Tab.DASHBOARD} label="İdarə Paneli" icon={LayoutDashboard} />
          <NavItem tab={Tab.POS} label="Satış Terminalı" icon={ShoppingCart} />
          <NavItem tab={Tab.INVENTORY} label="Anbar & Məhsullar" icon={Package} />
          <NavItem tab={Tab.ASSISTANT} label="Ağıllı Köməkçi" icon={Sparkles} />
          <NavItem tab={Tab.AUDIT} label="Anbar Tarixçəsi" icon={History} />
          <NavItem tab={Tab.SETTINGS} label="Tənzimləmələr" icon={Settings} />
        </nav>

        <div className="p-4 border-t border-slate-100">
          <button className="flex items-center gap-3 w-full px-4 py-3 text-red-500 hover:bg-red-50 rounded-lg transition-colors">
            <LogOut size={20} />
            <span>Çıxış</span>
          </button>
        </div>
      </aside>

      {/* Main Content */}
      <main className="flex-1 flex flex-col h-screen overflow-hidden relative">
        {/* Mobile Header */}
        <header className="md:hidden bg-white border-b border-slate-200 p-4 flex items-center justify-between z-20">
          <div className="flex items-center gap-2 text-blue-700">
            <Package size={24} />
            <span className="font-bold">İnşaatERP</span>
          </div>
          <button onClick={() => setIsMobileMenuOpen(!isMobileMenuOpen)} className="p-2 text-slate-600">
            <Menu size={24} />
          </button>
        </header>

        {/* Mobile Menu Overlay */}
        {isMobileMenuOpen && (
          <div className="absolute inset-0 bg-white z-30 flex flex-col p-4 md:hidden">
            <div className="flex justify-end mb-4">
               <button onClick={() => setIsMobileMenuOpen(false)} className="p-2 bg-slate-100 rounded-full">
                 <LogOut className="rotate-180" size={20} />
               </button>
            </div>
            <nav className="space-y-2">
              <NavItem tab={Tab.DASHBOARD} label="İdarə Paneli" icon={LayoutDashboard} />
              <NavItem tab={Tab.POS} label="Satış Terminalı" icon={ShoppingCart} />
              <NavItem tab={Tab.INVENTORY} label="Anbar & Məhsullar" icon={Package} />
              <NavItem tab={Tab.ASSISTANT} label="Ağıllı Köməkçi" icon={Sparkles} />
              <NavItem tab={Tab.AUDIT} label="Anbar Tarixçəsi" icon={History} />
              <NavItem tab={Tab.SETTINGS} label="Tənzimləmələr" icon={Settings} />
            </nav>
          </div>
        )}

        {/* Content Area */}
        <div className="flex-1 overflow-auto p-4 md:p-8">
          <div className="max-w-7xl mx-auto h-full">
            <header className="mb-8 hidden md:block">
              <h1 className="text-2xl font-bold text-slate-800">
                {activeTab === Tab.DASHBOARD && 'Xoş Gəldiniz'}
                {activeTab === Tab.INVENTORY && 'Anbar İdarəetməsi'}
                {activeTab === Tab.POS && 'Satış Nöqtəsi'}
                {activeTab === Tab.ASSISTANT && 'Süni İntellekt Dəstəyi'}
                {activeTab === Tab.AUDIT && 'Anbar Hərəkətləri'}
                {activeTab === Tab.SETTINGS && 'Tənzimləmələr'}
              </h1>
              <p className="text-slate-500 text-sm">Tikinti materialları mağazası idarəetmə sistemi</p>
            </header>
            {renderContent()}
          </div>
