import React, { useState, useRef } from 'react';
import { Product, Category } from '../types';
import { Plus, Search, Trash2, AlertCircle, ArrowUpDown, ArrowUp, ArrowDown, X, Save, Upload, Download, FileSpreadsheet, Edit } from 'lucide-react';

interface InventoryProps {
  products: Product[];
  onAddProduct: (p: Product) => void;
  onDeleteProduct: (id: string) => void;
  onUpdateProduct: (p: Product) => void;
  onBulkAddProducts: (products: Product[]) => void;
  lowStockThreshold: number;
}

const Inventory: React.FC<InventoryProps> = ({ products, onAddProduct, onDeleteProduct, onUpdateProduct, lowStockThreshold, onBulkAddProducts }) => {
  const [showForm, setShowForm] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Edit State
  const [editingProduct, setEditingProduct] = useState<Product | null>(null);

  // Sorting & Filtering State
  const [sortConfig, setSortConfig] = useState<{ key: keyof Product; direction: 'asc' | 'desc' } | null>(null);
  const [filterCategory, setFilterCategory] = useState<string>('ALL');
  const [filterStock, setFilterStock] = useState<'ALL' | 'LOW'>('ALL');

  // New Product State
  const [newProduct, setNewProduct] = useState<Partial<Product>>({
    name: '',
    category: Category.OTHER,
    price: 0,
    cost: 0,
    stock: 0,
    unit: 'ədəd'
  });

  const handleSave = () => {
    if (!newProduct.name || !newProduct.price) return;

    const product: Product = {
      id: Date.now().toString(),
      name: newProduct.name,
      category: newProduct.category as Category,
      price: Number(newProduct.price),
      cost: Number(newProduct.cost),
      stock: Number(newProduct.stock),
      unit: newProduct.unit || 'ədəd'
    };

    onAddProduct(product);
    setShowForm(false);
    setNewProduct({ name: '', category: Category.OTHER, price: 0, cost: 0, stock: 0, unit: 'ədəd' });
  };

  const handleUpdateSave = () => {
    if (!editingProduct || !editingProduct.name || editingProduct.price < 0) return;
    onUpdateProduct(editingProduct);
    setEditingProduct(null);
  };

  const handleDownloadTemplate = () => {
    const headers = "name,category,price,cost,stock,unit";
    // Using simple CSV generation. Be wary of commas in data.
    const sample = "Yeni Məhsul,Digər,10.00,8.00,50,ədəd";
    const csvContent = "data:text/csv;charset=utf-8," + headers + "\n" + sample;
    const encodedUri = encodeURI(csvContent);
    const link = document.createElement("a");
    link.setAttribute("href", encodedUri);
    link.setAttribute("download", "mehsul_sablonu.csv");
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const handleFileUpload = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (e) => {
      const text = e.target?.result as string;
      if (!text) return;

      const lines = text.split('\n');
      const parsedProducts: Product[] = [];

      // Start from index 1 to skip header
      for (let i = 1; i < lines.length; i++) {
          const line = lines[i].trim();
          if (!line) continue;

          // Simple CSV split
          const parts = line.split(',');
          // Handle potential issues if description has commas (not supported in this simple version)
          if (parts.length < 6) continue;

          const [name, category, price, cost, stock, unit] = parts;

          // Basic validation
          if (name && !isNaN(Number(price))) {
              const matchedCategory = Object.values(Category).find(c => c === category.trim()) || Category.OTHER;

              parsedProducts.push({
                  id: Date.now().toString() + Math.random().toString().slice(2, 6) + i,
                  name: name.trim(),
                  category: matchedCategory as Category,
                  price: Number(price),
                  cost: Number(cost) || 0,
                  stock: Number(stock) || 0,
                  unit: unit?.trim() || 'ədəd'
              });
          }
      }

      if (parsedProducts.length > 0) {
          onBulkAddProducts(parsedProducts);
          if (fileInputRef.current) fileInputRef.current.value = '';
          alert(`${parsedProducts.length} məhsul uğurla idxal edildi!`);
      } else {
          alert('Fayldan heç bir məhsul oxuna bilmədi. Zəhmət olmasa şablonu yoxlayın.');
      }
    };
    reader.readAsText(file);
  };

  const handleSort = (key: keyof Product) => {
    let direction: 'asc' | 'desc' = 'asc';
    if (sortConfig && sortConfig.key === key && sortConfig.direction === 'asc') {
      direction = 'desc';
    }
    setSortConfig({ key, direction });
  };

  const getSortIcon = (columnKey: keyof Product) => {
    if (sortConfig?.key !== columnKey) return <ArrowUpDown size={14} className="text-slate-300" />;
    return sortConfig.direction === 'asc' ? 
      <ArrowUp size={14} className="text-blue-600" /> : 
      <ArrowDown size={14} className="text-blue-600" />;
  };

  // Filter Logic
  const filteredProducts = products.filter(p => {
    const matchesSearch = p.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
                          p.category.toLowerCase().includes(searchTerm.toLowerCase());
    const matchesCategory = filterCategory === 'ALL' || p.category === filterCategory;
    const matchesStock = filterStock === 'ALL' || (filterStock === 'LOW' && p.stock < lowStockThreshold);

    return matchesSearch && matchesCategory && matchesStock;
  });

  // Sort Logic
  const sortedProducts = [...filteredProducts].sort((a, b) => {
    if (!sortConfig) return 0;
    const { key, direction } = sortConfig;

    if (key === 'name' || key === 'category') {
       const valA = a[key].toLowerCase();
       const valB = b[key].toLowerCase();
       if (valA < valB) return direction === 'asc' ? -1 : 1;
       if (valA > valB) return direction === 'asc' ? 1 : -1;
       return 0;
    }

    // Numeric sort
    const valA = Number(a[key as keyof Product]);
    const valB = Number(b[key as keyof Product]);
    return direction === 'asc' ? valA - valB : valB - valA;
  });

  return (
    <div className="space-y-6 animate-fade-in">
      {/* Hidden File Input */}
      <input 
        type="file" 
        ref={fileInputRef} 
        onChange={handleFileUpload} 
        className="hidden" 
        accept=".csv" 
      />

      {/* Controls Header */}
      <div className="flex flex-col xl:flex-row justify-between items-start xl:items-center gap-4 bg-white p-4 rounded-xl shadow-sm border border-slate-100">

        {/* Search */}
        <div className="relative w-full xl:w-80">
          <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 text-slate-400" size={20} />
          <input 
            type="text" 
            placeholder="Axtar..." 
            className="w-full pl-10 pr-4 py-2 border border-slate-200 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500"
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
          />
        </div>

        {/* Filters */}
        <div className="flex flex-col sm:flex-row gap-4 w-full xl:w-auto overflow-x-auto pb-2 sm:pb-0">
          <select 
            className="border border-slate-200 rounded-lg px-3 py-2 text-slate-700 focus:outline-none focus:ring-2 focus:ring-blue-500 bg-white"
            value={filterCategory}
            onChange={(e) => setFilterCategory(e.target.value)}
          >
            <option value="ALL">Bütün Kateqoriyalar</option>
            {Object.values(Category).map(c => <option key={c} value={c}>{c}</option>)}
          </select>

          <button 
            onClick={() => setFilterStock(filterStock === 'ALL' ? 'LOW' : 'ALL')}
            className={`flex items-center justify-center gap-2 px-4 py-2 rounded-lg border transition-colors whitespace-nowrap ${
              filterStock === 'LOW' 
                ? 'bg-amber-50 border-amber-200 text-amber-700 font-medium' 
                : 'bg-white border-slate-200 text-slate-600 hover:bg-slate-50'
            }`}
          >
            <AlertCircle size={18} className={filterStock === 'LOW' ? 'text-amber-600' : 'text-slate-400'} />
            {filterStock === 'LOW' ? 'Kritik Say' : 'Hamısı'}
          </button>

          {/* Import/Export Actions */}
          <div className="flex items-center gap-2 border-l pl-4 border-slate-200">
            <button 
              onClick={handleDownloadTemplate} 
              className="p-2 text-slate-500 hover:text-blue-600 hover:bg-blue-50 rounded-lg transition-colors"
              title="Şablonu yüklə"
            >
              <Download size={20} />
            </button>
            <button 
              onClick={() => fileInputRef.current?.click()} 
              className="p-2 text-slate-500 hover:text-blue-600 hover:bg-blue-50 rounded-lg transition-colors"
              title="CSV İdxal et"
            >
              <Upload size={20} />
            </button>
          </div>

          <button 
            onClick={() => setShowForm(!showForm)}
            className={`flex items-center justify-center gap-2 px-4 py-2 rounded-lg transition-colors whitespace-nowrap ${
              showForm ? 'bg-slate-100 text-slate-700' : 'bg-blue-600 hover:bg-blue-700 text-white'
            }`}
          >
            {showForm ? <X size={20} /> : <Plus size={20} />}
            <span className="hidden sm:inline">{showForm ? 'Bağla' : 'Yeni Məhsul'}</span>
            <span className="sm:hidden">{showForm ? 'Bağla' : 'Yeni'}</span>
          </button>
        </div>
      </div>

      {/* Inline Add Product Form */}
      {showForm && (
        <div className="bg-white rounded-xl shadow-sm border border-blue-200 p-6 animate-fade-in-down">
          <h3 className="text-lg font-bold text-slate-800 mb-4 flex items-center gap-2">
            <Plus className="text-blue-600" size={20} /> Yeni Məhsul Məlumatları
          </h3>
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-6 gap-4">
             <div className="xl:col-span-2">
                <label className="block text-sm font-medium text-slate-700 mb-1">Məhsul Adı</label>
                <input 
                  type="text" 
                  className="w-full border border-slate-300 p-2 rounded-lg focus:ring-2 focus:ring-blue-500 outline-none"
                  placeholder="Məs: Sement 50kq"
                  value={newProduct.name}
                  onChange={e => setNewProduct({...newProduct, name: e.target.value})}
                />
             </div>
             <div className="xl:col-span-1">
                <label className="block text-sm font-medium text-slate-700 mb-1">Kateqoriya</label>
                <select 
                  className="w-full border border-slate-300 p-2 rounded-lg outline-none focus:ring-2 focus:ring-blue-500 bg-white"
                  value={newProduct.category}
                  onChange={e => setNewProduct({...newProduct, category: e.target.value as Category})}
                >
                  {Object.values(Category).map(c => <option key={c} value={c}>{c}</option>)}
                </select>
             </div>
             <div>
                <label className="block text-sm font-medium text-slate-700 mb-1">Vahid</label>
                <input 
                  type="text" 
                  placeholder="ədəd, kq..."
                  className="w-full border border-slate-300 p-2 rounded-lg outline-none focus:ring-2 focus:ring-blue-500"
                  value={newProduct.unit}
                  onChange={e => setNewProduct({...newProduct, unit: e.target.value})}
                />
             </div>
             <div>
                <label className="block text-sm font-medium text-slate-700 mb-1">Maya Dəyəri (₼)</label>
                <input 
                  type="number" 
                  min="0"
                  step="0.01"
                  className="w-full border border-slate-300 p-2 rounded-lg outline-none focus:ring-2 focus:ring-blue-500"
                  value={newProduct.cost}
                  onChange={e => setNewProduct({...newProduct, cost: Number(e.target.value)})}
                />
             </div>
             <div>
                <label className="block text-sm font-medium text-slate-700 mb-1">Satış Qiyməti (₼)</label>
                <input 
                  type="number" 
                  min="0"
                  step="0.01"
