import React, { useState } from 'react';
import { Product, CartItem, Sale } from '../types';
import { Search, ShoppingCart, Minus, Plus, Trash2, CheckCircle, Package } from 'lucide-react';

interface POSProps {
  products: Product[];
  onCompleteSale: (sale: Sale) => void;
}

const POS: React.FC<POSProps> = ({ products, onCompleteSale }) => {
  const [cart, setCart] = useState<CartItem[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [successMsg, setSuccessMsg] = useState('');

  // Mobile Tab State
  const [mobileTab, setMobileTab] = useState<'products' | 'cart'>('products');

  const addToCart = (product: Product) => {
    setCart(prev => {
      const existing = prev.find(item => item.id === product.id);
      if (existing) {
        if (existing.quantity >= product.stock) return prev; // Stock limit check
        return prev.map(item => item.id === product.id ? { ...item, quantity: item.quantity + 1 } : item);
      }
      return [...prev, { ...product, quantity: 1 }];
    });
  };

  const removeFromCart = (id: string) => {
    setCart(prev => prev.filter(item => item.id !== id));
  };

  const updateQuantity = (id: string, delta: number) => {
    setCart(prev => {
      return prev.map(item => {
        if (item.id === id) {
          const newQty = item.quantity + delta;
          if (newQty > item.stock) return item; // Cannot exceed stock
          if (newQty < 1) return item;
          return { ...item, quantity: newQty };
        }
        return item;
      });
    });
  };

  const handleCheckout = () => {
    if (cart.length === 0) return;

    const total = cart.reduce((sum, item) => sum + (item.price * item.quantity), 0);
    const totalCost = cart.reduce((sum, item) => sum + (item.cost * item.quantity), 0);

    const sale: Sale = {
      id: Date.now().toString(),
      date: new Date().toISOString(),
      items: [...cart],
      total: total,
      profit: total - totalCost
    };

    onCompleteSale(sale);
    setCart([]);
    setSuccessMsg('Satış uğurla tamamlandı!');
    setTimeout(() => setSuccessMsg(''), 3000);
  };

  const filteredProducts = products.filter(p => 
    p.name.toLowerCase().includes(searchTerm.toLowerCase()) && p.stock > 0
  );

  const cartTotal = cart.reduce((sum, item) => sum + (item.price * item.quantity), 0);
  const cartItemCount = cart.reduce((sum, item) => sum + item.quantity, 0);

  return (
    <div className="flex flex-col h-[calc(100vh-100px)] md:h-[calc(100vh-140px)] animate-fade-in relative">

      {/* Mobile Tab Switcher */}
      <div className="md:hidden flex bg-white p-1 rounded-xl shadow-sm border border-slate-200 mb-4 shrink-0">
        <button 
          onClick={() => setMobileTab('products')}
          className={`flex-1 py-2 rounded-lg text-sm font-medium transition-all ${
            mobileTab === 'products' ? 'bg-blue-600 text-white shadow-md' : 'text-slate-500'
          }`}
        >
          Məhsullar
        </button>
        <button 
          onClick={() => setMobileTab('cart')}
          className={`flex-1 py-2 rounded-lg text-sm font-medium transition-all flex items-center justify-center gap-2 ${
            mobileTab === 'cart' ? 'bg-blue-600 text-white shadow-md' : 'text-slate-500'
          }`}
        >
          Səbət
          {cartItemCount > 0 && (
            <span className={`text-xs px-1.5 py-0.5 rounded-full ${mobileTab === 'cart' ? 'bg-white text-blue-600' : 'bg-blue-100 text-blue-600'}`}>
              {cartItemCount}
            </span>
          )}
        </button>
      </div>

      <div className="flex-1 flex flex-col lg:flex-row gap-6 overflow-hidden">

        {/* Left: Product Grid */}
        <div className={`flex-1 flex flex-col gap-4 bg-white rounded-xl shadow-sm border border-slate-100 p-4 h-full overflow-hidden ${mobileTab === 'cart' ? 'hidden md:flex' : 'flex'}`}>
           <div className="relative shrink-0">
            <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 text-slate-400" size={20} />
            <input 
              type="text" 
              placeholder="Satış üçün məhsul axtar..." 
              className="w-full pl-10 pr-4 py-3 border border-slate-200 rounded-xl focus:outline-none focus:ring-2 focus:ring-blue-500 bg-slate-50 transition-all"
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
            />
          </div>

          <div className="flex-1 overflow-y-auto grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-4 p-1 pb-20 md:pb-0">
            {filteredProducts.map(product => (
              <div 
                key={product.id} 
                onClick={() => {
                   addToCart(product);
                   // Optional: give feedback or switch tab
                }}
                className="bg-white border border-slate-200 rounded-xl p-4 cursor-pointer hover:border-blue-500 hover:shadow-md transition-all flex flex-col justify-between group h-32 md:h-40"
              >
                <div>
                  <h4 className="font-semibold text-slate-800 line-clamp-2 leading-tight">{product.name}</h4>
                  <p className="text-xs text-slate-500 mt-1">{product.stock} {product.unit} qalıb</p>
                </div>
                <div className="flex justify-between items-end mt-2">
                  <span className="font-bold text-blue-600 text-lg">{product.price.toFixed(2)} ₼</span>
                  <div className="bg-slate-100 p-2 rounded-full text-slate-400 group-hover:bg-blue-600 group-hover:text-white transition-colors">
                    <Plus size={16} />
                  </div>
                </div>
              </div>
            ))}
            {filteredProducts.length === 0 && (
               <div className="col-span-full flex flex-col items-center justify-center text-slate-400 h-40">
                 <Package size={40} className="mb-2 opacity-20"/>
                 Məhsul tapılmadı.
               </div>
            )}
          </div>
        </div>

        {/* Right: Cart */}
        <div className={`w-full lg:w-96 bg-white rounded-xl shadow-lg border border-slate-200 flex flex-col h-full overflow-hidden ${mobileTab === 'products' ? 'hidden md:flex' : 'flex'}`}>
          <div className="p-4 bg-slate-50 border-b border-slate-100 flex justify-between items-center shrink-0">
            <h2 className="font-bold text-lg text-slate-800 flex items-center gap-2">
              <ShoppingCart size={20} /> Cari Sifariş
            </h2>
            <span className="bg-blue-100 text-blue-700 px-3 py-1 rounded-full text-xs font-bold">
              {cart.length} növ
            </span>
          </div>

          <div className="flex-1 overflow-y-auto p-4 space-y-4">
            {cart.map(item => (
              <div key={item.id} className="flex justify-between items-center bg-white p-3 rounded-xl border border-slate-100 shadow-sm">
                <div className="flex-1 min-w-0 mr-2">
                  <h4 className="text-sm font-medium text-slate-900 truncate">{item.name}</h4>
                  <div className="text-xs text-slate-500 font-mono mt-0.5">{item.price.toFixed(2)} ₼</div>
                </div>
                <div className="flex items-center gap-3 shrink-0">
                  <div className="flex items-center gap-1 bg-slate-100 rounded-lg p-1">
                    <button onClick={() => updateQuantity(item.id, -1)} className="p-1 hover:bg-white rounded shadow-sm disabled:opacity-50">
                      <Minus size={14} />
                    </button>
                    <span className="w-8 text-center text-sm font-bold">{item.quantity}</span>
                    <button onClick={() => updateQuantity(item.id, 1)} className="p-1 hover:bg-white rounded shadow-sm">
                      <Plus size={14} />
                    </button>
                  </div>
                  <button onClick={() => removeFromCart(item.id)} className="text-slate-400 hover:text-red-500 p-1">
                    <Trash2 size={18} />
                  </button>
                </div>
              </div>
            ))}
            {cart.length === 0 && (
              <div className="h-full flex flex-col items-center justify-center text-slate-400 opacity-50">
                <ShoppingCart size={64} className="mb-4" />
                <p>Səbət boşdur</p>
              </div>
            )}
          </div>

          <div className="p-4 bg-slate-50 border-t border-slate-200 shrink-0 pb-20 md:pb-4">
            <div className="flex justify-between items-center mb-4">
              <span className="text-slate-600 font-medium">Cəmi:</span>
              <span className="text-3xl font-bold text-slate-900 tracking-tight">{cartTotal.toFixed(2)} ₼</span>
            </div>
            <button 
              onClick={handleCheckout}
              disabled={cart.length === 0}
              className={`w-full py-4 rounded-xl font-bold text-lg flex items-center justify-center gap-2 transition-all ${
                cart.length > 0 
                ? 'bg-blue-600 hover:bg-blue-700 text-white shadow-lg shadow-blue-500/30 active:scale-[0.98]' 
                : 'bg-slate-200 text-slate-400 cursor-not-allowed'
              }`}
            >
              Satışı Tamamla
            </button>
            {successMsg && (
              <div className="mt-3 text-center text-sm font-bold text-emerald-600 flex items-center justify-center gap-1 animate-pulse bg-emerald-50 py-2 rounded-lg border border-emerald-100">
                <CheckCircle size={16} /> {successMsg}
              </div>
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

