import React, { useState, useRef } from 'react';
import { Product, Category } from '../types';
import { Plus, Search, Trash2, AlertCircle, ArrowUpDown, ArrowUp, ArrowDown, X, Save, Upload, Download, FileSpreadsheet, Edit, MoreHorizontal, Package } from 'lucide-react';

interface InventoryProps {
  products: Product[];
  onAddProduct: (p: Product) => void;
  onDeleteProduct: (id: string) => void;
  onUpdateProduct: (p: Product) => void;
  onBulkAddProducts: (products: Product[]) => void;
  lowStockThreshold: number;
}

const Inventory: React.FC<InventoryProps> = ({ products, onAddProduct, onDeleteProduct, onUpdateProduct, lowStockThreshold, onBulkAddProducts }) => {
  const [showForm, setShowForm] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Edit State
  const [editingProduct, setEditingProduct] = useState<Product | null>(null);

  // Sorting & Filtering State
  const [sortConfig, setSortConfig] = useState<{ key: keyof Product; direction: 'asc' | 'desc' } | null>(null);
  const [filterCategory, setFilterCategory] = useState<string>('ALL');
  const [filterStock, setFilterStock] = useState<'ALL' | 'LOW'>('ALL');

  // New Product State
  const [newProduct, setNewProduct] = useState<Partial<Product>>({
    name: '',
    category: Category.OTHER,
    price: 0,
    cost: 0,
    stock: 0,
    unit: 'ədəd'
  });

  const handleSave = () => {
    if (!newProduct.name || !newProduct.price) return;

    const product: Product = {
      id: Date.now().toString(),
      name: newProduct.name,
      category: newProduct.category as Category,
      price: Number(newProduct.price),
      cost: Number(newProduct.cost),
      stock: Number(newProduct.stock),
      unit: newProduct.unit || 'ədəd'
    };

    onAddProduct(product);
    setShowForm(false);
    setNewProduct({ name: '', category: Category.OTHER, price: 0, cost: 0, stock: 0, unit: 'ədəd' });
  };

  const handleUpdateSave = () => {
    if (!editingProduct || !editingProduct.name || editingProduct.price < 0) return;
    onUpdateProduct(editingProduct);
    setEditingProduct(null);
  };

  const handleDownloadTemplate = () => {
    const headers = "name,category,price,cost,stock,unit";
    // Using simple CSV generation. Be wary of commas in data.
    const sample = "Yeni Məhsul,Digər,10.00,8.00,50,ədəd";
    const csvContent = "data:text/csv;charset=utf-8," + headers + "\n" + sample;
    const encodedUri = encodeURI(csvContent);
    const link = document.createElement("a");
    link.setAttribute("href", encodedUri);
    link.setAttribute("download", "mehsul_sablonu.csv");
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const handleFileUpload = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (e) => {
      const text = e.target?.result as string;
      if (!text) return;

      const lines = text.split('\n');
      const parsedProducts: Product[] = [];

      // Start from index 1 to skip header
      for (let i = 1; i < lines.length; i++) {
          const line = lines[i].trim();
          if (!line) continue;

          // Simple CSV split
          const parts = line.split(',');
          // Handle potential issues if description has commas (not supported in this simple version)
          if (parts.length < 6) continue;

          const [name, category, price, cost, stock, unit] = parts;

          // Basic validation
          if (name && !isNaN(Number(price))) {
              const matchedCategory = Object.values(Category).find(c => c === category.trim()) || Category.OTHER;

              parsedProducts.push({
                  id: Date.now().toString() + Math.random().toString().slice(2, 6) + i,
                  name: name.trim(),
                  category: matchedCategory as Category,
                  price: Number(price),
                  cost: Number(cost) || 0,
                  stock: Number(stock) || 0,
                  unit: unit?.trim() || 'ədəd'
              });
          }
      }

      if (parsedProducts.length > 0) {
          onBulkAddProducts(parsedProducts);
          if (fileInputRef.current) fileInputRef.current.value = '';
          alert(`${parsedProducts.length} məhsul uğurla idxal edildi!`);
      } else {
          alert('Fayldan heç bir məhsul oxuna bilmədi. Zəhmət olmasa şablonu yoxlayın.');
      }
    };
    reader.readAsText(file);
  };

  const handleSort = (key: keyof Product) => {
    let direction: 'asc' | 'desc' = 'asc';
    if (sortConfig && sortConfig.key === key && sortConfig.direction === 'asc') {
      direction = 'desc';
    }
    setSortConfig({ key, direction });
  };

  const getSortIcon = (columnKey: keyof Product) => {
    if (sortConfig?.key !== columnKey) return <ArrowUpDown size={14} className="text-slate-300" />;
    return sortConfig.direction === 'asc' ? 
      <ArrowUp size={14} className="text-blue-600" /> : 
      <ArrowDown size={14} className="text-blue-600" />;
  };

  // Filter Logic
  const filteredProducts = products.filter(p => {
    const matchesSearch = p.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
                          p.category.toLowerCase().includes(searchTerm.toLowerCase());
    const matchesCategory = filterCategory === 'ALL' || p.category === filterCategory;
    const matchesStock = filterStock === 'ALL' || (filterStock === 'LOW' && p.stock < lowStockThreshold);

    return matchesSearch && matchesCategory && matchesStock;
  });

  // Sort Logic
  const sortedProducts = [...filteredProducts].sort((a, b) => {
    if (!sortConfig) return 0;
    const { key, direction } = sortConfig;

    if (key === 'name' || key === 'category') {
       const valA = a[key].toLowerCase();
       const valB = b[key].toLowerCase();
       if (valA < valB) return direction === 'asc' ? -1 : 1;
       if (valA > valB) return direction === 'asc' ? 1 : -1;
       return 0;
    }

    // Numeric sort
    const valA = Number(a[key as keyof Product]);
    const valB = Number(b[key as keyof Product]);
    return direction === 'asc' ? valA - valB : valB - valA;
  });

  // Mobile Product Card Component
  const MobileProductCard = ({ product }: { product: Product }) => (
    <div className="bg-white p-4 rounded-xl border border-slate-200 shadow-sm space-y-3">
      <div className="flex justify-between items-start">
        <div>
          <h3 className="font-bold text-slate-800 text-lg">{product.name}</h3>
          <span className="inline-block mt-1 px-2 py-0.5 bg-slate-100 text-slate-600 text-xs rounded-full">
            {product.category}
          </span>
        </div>
        <div className="text-right">
           <div className="font-bold text-emerald-600 text-lg">{product.price.toFixed(2)} ₼</div>
           <div className="text-xs text-slate-400">Maya: {product.cost.toFixed(2)} ₼</div>
        </div>
      </div>

      <div className="flex justify-between items-center pt-2 border-t border-slate-50">
        <div className={`flex items-center gap-1.5 font-medium ${product.stock < lowStockThreshold ? 'text-amber-600' : 'text-slate-600'}`}>
          <Package size={16} />
          {product.stock} {product.unit}
          {product.stock < lowStockThreshold && <AlertCircle size={16} className="text-amber-500" />}
        </div>

        <div className="flex gap-2">
          <button 
            onClick={() => setEditingProduct({...product})}
            className="p-2 bg-slate-100 text-slate-600 rounded-lg hover:bg-slate-200 active:bg-slate-300 transition-colors"
          >
            <Edit size={18} />
          </button>
          <button 
            onClick={() => onDeleteProduct(product.id)}
            className="p-2 bg-red-50 text-red-500 rounded-lg hover:bg-red-100 active:bg-red-200 transition-colors"
          >
            <Trash2 size={18} />
          </button>
        </div>
      </div>
    </div>
  );

  // Common Form Fields
  const ProductFormFields = ({ prod, setProd }: { prod: any, setProd: any }) => (
    <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-6 gap-4">
      <div className="xl:col-span-2">
        <label className="block text-sm font-medium text-slate-700 mb-1">Məhsul Adı</label>
        <input 
          type="text" 
          className="w-full border border-slate-300 p-3 rounded-lg focus:ring-2 focus:ring-blue-500 outline-none transition-all"
          placeholder="Məs: Sement 50kq"
          value={prod.name}
          onChange={e => setProd({...prod, name: e.target.value})}
        />
      </div>
      <div className="xl:col-span-1">
        <label className="block text-sm font-medium text-slate-700 mb-1">Kateqoriya</label>
        <select 
          className="w-full border border-slate-300 p-3 rounded-lg outline-none focus:ring-2 focus:ring-blue-500 bg-white"
          value={prod.category}
          onChange={e => setProd({...prod, category: e.target.value as Category})}
        >
          {Object.values(Category).map(c => <option key={c} value={c}>{c}</option>)}
        </select>
      </div>
      <div>
        <label className="block text-sm font-medium text-slate-700 mb-1">Vahid</label>
        <input 
          type="text" 
          placeholder="ədəd..."
          className="w-full border border-slate-300 p-3 rounded-lg outline-none focus:ring-2 focus:ring-blue-500"
          value={prod.unit}
          onChange={e => setProd({...prod, unit: e.target.value})}
        />
      </div>
      <div>
        <label className="block text-sm font-medium text-slate-700 mb-1">Maya (₼)</label>
        <input 
          type="number" 
          min="0"
          step="0.01"
          className="w-full border border-slate-300 p-3 rounded-lg outline-none focus:ring-2 focus:ring-blue-500"
          value={prod.cost}
          onChange={e => setProd({...prod, cost: Number(e.target.value)})}
        />
      </div>
      <div>
        <label className="block text-sm font-medium text-slate-700 mb-1">Satış (₼)</label>
        <input 
          type="number" 
          min="0"
          step="0.01"
          className="w-full border border-slate-300 p-3 rounded-lg outline-none focus:ring-2 focus:ring-blue-500"
          value={prod.price}
          onChange={e => setProd({...prod, price: Number(e.target.value)})}
        />
      </div>
      <div>
        <label className="block text-sm font-medium text-slate-700 mb-1">Say</label>
        <input 
          type="number" 
          min="0"
          className="w-full border border-slate-300 p-3 rounded-lg outline-none focus:ring-2 focus:ring-blue-500"
          value={prod.stock}
          onChange={e => setProd({...prod, stock: Number(e.target.value)})}
        />
      </div>
    </div>
  );

  return (
    <div className="space-y-6 animate-fade-in pb-20 md:pb-0">
      {/* Hidden File Input */}
      <input 
        type="file" 
        ref={fileInputRef} 
        onChange={handleFileUpload} 
        className="hidden" 
        accept=".csv" 
      />

      {/* Controls Header */}
      <div className="bg-white p-4 rounded-xl shadow-sm border border-slate-100 flex flex-col xl:flex-row gap-4">

        {/* Search */}
        <div className="relative w-full xl:w-96">
          <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 text-slate-400" size={20} />
          <input 
            type="text" 
            placeholder="Məhsul axtar..." 
            className="w-full pl-10 pr-4 py-2.5 border border-slate-200 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500 transition-shadow"
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
          />
        </div>

        {/* Filters - Scrollable Row on Mobile */}
        <div className="flex flex-1 gap-3 overflow-x-auto pb-1 xl:pb-0 no-scrollbar items-center">
          <select 
            className="border border-slate-200 rounded-lg px-3 py-2.5 text-slate-700 bg-white focus:outline-none focus:ring-2 focus:ring-blue-500 min-w-[160px]"
            value={filterCategory}
            onChange={(e) => setFilterCategory(e.target.value)}
          >
            <option value="ALL">Bütün Kateqoriyalar</option>
            {Object.values(Category).map(c => <option key={c} value={c}>{c}</option>)}
          </select>

          <button 
            onClick={() => setFilterStock(filterStock === 'ALL' ? 'LOW' : 'ALL')}
            className={`flex items-center gap-2 px-4 py-2.5 rounded-lg border whitespace-nowrap transition-colors ${
              filterStock === 'LOW' 
                ? 'bg-amber-50 border-amber-200 text-amber-700 font-medium' 
                : 'bg-white border-slate-200 text-slate-600 hover:bg-slate-50'
            }`}
          >
            <AlertCircle size={18} className={filterStock === 'LOW' ? 'text-amber-600' : 'text-slate-400'} />
            <span className="hidden sm:inline">{filterStock === 'LOW' ? 'Kritik Say' : 'Stok Vəziyyəti'}</span>
            <span className="sm:hidden">{filterStock === 'LOW' ? 'Kritik' : 'Stok'}</span>
          </button>

          <div className="flex items-center gap-1 border-l pl-3 border-slate-200 ml-auto xl:ml-0">
             <button 
              onClick={handleDownloadTemplate} 
              className="p-2.5 text-slate-500 hover:text-blue-600 hover:bg-blue-50 rounded-lg transition-colors"
              title="Şablonu yüklə"
            >
              <Download size={20} />
            </button>
            <button 
              onClick={() => fileInputRef.current?.click()} 
              className="p-2.5 text-slate-500 hover:text-blue-600 hover:bg-blue-50 rounded-lg transition-colors"
              title="CSV İdxal et"
            >
              <Upload size={20} />
            </button>
          </div>

           <button 
            onClick={() => setShowForm(!showForm)}
            className={`flex items-center gap-2 px-5 py-2.5 rounded-lg transition-colors whitespace-nowrap shadow-sm font-medium ml-2 ${
              showForm ? 'bg-slate-100 text-slate-700' : 'bg-blue-600 hover:bg-blue-700 text-white'
            }`}
          >
            {showForm ? <X size={20} /> : <Plus size={20} />}
            <span className="hidden sm:inline">{showForm ? 'Bağla' : 'Yeni Məhsul'}</span>
            <span className="sm:hidden">{showForm ? 'Bağla' : 'Yeni'}</span>
          </button>
        </div>
      </div>

      {/* Inline Add Product Form - Desktop/Tablet */}
      {showForm && (
        <div className="bg-white rounded-xl shadow-md border border-blue-100 p-6 animate-fade-in-down">
          <h3 className="text-lg font-bold text-slate-800 mb-5 flex items-center gap-2 border-b border-slate-100 pb-2">
            <Plus className="text-blue-600" size={20} /> Yeni Məhsul Məlumatları
          </h3>
          <ProductFormFields prod={newProduct} setProd={setNewProduct} />
          <div className="flex justify-end gap-3 mt-6">
            <button 
              onClick={() => setShowForm(false)}
              className="px-6 py-2.5 rounded-lg border border-slate-200 text-slate-600 hover:bg-slate-50 font-medium transition-colors"
            >
              Ləğv et
            </button>
            <button 
              onClick={handleSave}
              className="px-6 py-2.5 rounded-lg bg-emerald-600 hover:bg-emerald-700 text-white font-medium flex items-center gap-2 shadow-sm shadow-emerald-200 transition-all hover:scale-[1.02]"
            >
              <Save size={18} />
              Əlavə et
            </button>
          </div>
        </div>
      )}

      {/* Edit Modal - Responsive (Full screen on mobile) */}
      {editingProduct && (
        <div className="fixed inset-0 bg-black/60 backdrop-blur-sm flex items-center justify-center z-50 md:p-4">
          <div className="bg-white w-full h-full md:h-auto md:rounded-2xl md:max-w-4xl shadow-2xl flex flex-col md:max-h-[90vh] animate-scale-in">
            <div className="bg-white px-6 py-4 border-b border-slate-100 flex justify-between items-center sticky top-0 z-10">
              <h3 className="text-lg font-bold text-slate-800 flex items-center gap-2">
                <Edit size={20} className="text-amber-600"/> Məhsulu Redaktə Et
              </h3>
              <button 
                onClick={() => setEditingProduct(null)} 
                className="text-slate-400 hover:text-slate-600 p-2 rounded-full hover:bg-slate-100 transition-colors"
              >
                <X size={24} />
              </button>
            </div>

            <div className="flex-1 p-6 overflow-y-auto">
               <ProductFormFields prod={editingProduct} setProd={setEditingProduct} />

               {/* Additional Edit-specific UI like quick stock adjust */}
               <div className="mt-8 p-4 bg-amber-50 rounded-xl border border-amber-100">
                  <label className="block text-sm font-bold text-amber-800 mb-2 flex items-center gap-2">
                    <AlertCircle size={18}/> Sürətli Anbar Düzəlişi
                  </label>
                  <div className="flex items-center gap-4">
                    <button 
                      onClick={() => setEditingProduct({...editingProduct, stock: Math.max(0, editingProduct.stock - 1)})}
                      className="w-12 h-12 flex items-center justify-center bg-white border border-amber-200 rounded-lg text-amber-700 hover:bg-amber-100 text-xl font-bold"
                    >
                      -
                    </button>
                    <div className="text-2xl font-bold text-slate-800 w-24 text-center">
                      {editingProduct.stock}
                    </div>
                    <button 
                       onClick={() => setEditingProduct({...editingProduct, stock: editingProduct.stock + 1})}
                       className="w-12 h-12 flex items-center justify-center bg-white border border-amber-200 rounded-lg text-amber-700 hover:bg-amber-100 text-xl font-bold"
                    >
                      +
                    </button>
                  </div>
               </div>
            </div>

            <div className="bg-slate-50 px-6 py-4 border-t border-slate-200 flex justify-end gap-3 sticky bottom-0 z-10">
              <button 
                onClick={() => setEditingProduct(null)}
                className="flex-1 md:flex-none px-6 py-3 md:py-2.5 rounded-xl border border-slate-300 text-slate-700 hover:bg-white font-medium transition-colors"
              >
                Ləğv et
              </button>
              <button 
                onClick={handleUpdateSave}
                className="flex-1 md:flex-none px-6 py-3 md:py-2.5 rounded-xl bg-amber-500 hover:bg-amber-600 text-white font-medium flex justify-center items-center gap-2 shadow-lg shadow-amber-200 transition-all active:scale-95"
              >
                <Save size={18} />
                Yadda Saxla
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Product List - Mobile (Cards) & Desktop (Table) */}

      {/* Mobile Card View */}
      <div className="md:hidden space-y-4">
        {sortedProducts.map(product => (
          <MobileProductCard key={product.id} product={product} />
        ))}
        {sortedProducts.length === 0 && (
          <div className="text-center py-12 text-slate-400 bg-white rounded-xl border border-slate-100 border-dashed">
            <Package size={48} className="mx-auto mb-2 opacity-20" />
            <p>Məhsul tapılmadı.</p>
          </div>
        )}
      </div>

      {/* Desktop Table View */}
      <div className="hidden md:block bg-white rounded-xl shadow-sm border border-slate-100 overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full text-left border-collapse">
            <thead>
              <tr className="bg-slate-50 text-slate-600 text-sm font-medium border-b border-slate-100 select-none">
                <th className="p-4 cursor-pointer hover:bg-slate-100 transition-colors" onClick={() => handleSort('name')}>
                  <div className="flex items-center gap-2">Məhsul Adı {getSortIcon('name')}</div>
                </th>
                <th className="p-4 cursor-pointer hover:bg-slate-100 transition-colors" onClick={() => handleSort('category')}>
                  <div className="flex items-center gap-2">Kateqoriya {getSortIcon('category')}</div>
                </th>
                <th className="p-4 cursor-pointer hover:bg-slate-100 transition-colors" onClick={() => handleSort('cost')}>
                   <div className="flex items-center gap-2">Alış {getSortIcon('cost')}</div>
                </th>
                <th className="p-4 cursor-pointer hover:bg-slate-100 transition-colors" onClick={() => handleSort('price')}>
                   <div className="flex items-center gap-2">Satış {getSortIcon('price')}</div>
                </th>
                <th className="p-4 cursor-pointer hover:bg-slate-100 transition-colors" onClick={() => handleSort('stock')}>
                   <div className="flex items-center gap-2">Anbar {getSortIcon('stock')}</div>
                </th>
                <th className="p-4 text-right">Əməliyyatlar</th>
              </tr>
            </thead>
            <tbody>
              {sortedProducts.map(product => (
                <tr key={product.id} className="border-b border-slate-50 hover:bg-slate-50 transition-colors group">
                  <td className="p-4 font-medium text-slate-800">{product.name}</td>
                  <td className="p-4">
                    <span className="px-2.5 py-1 bg-slate-100 text-slate-600 text-xs rounded-full whitespace-nowrap border border-slate-200">
                      {product.category}
                    </span>
                  </td>
                  <td className="p-4 text-slate-500 font-mono text-sm">{product.cost.toFixed(2)} ₼</td>
                  <td className="p-4 font-bold text-emerald-600 font-mono text-sm">{product.price.toFixed(2)} ₼</td>
                  <td className="p-4">
                    <div className={`flex items-center gap-2 ${product.stock < lowStockThreshold ? 'text-amber-600 font-bold bg-amber-50 px-2 py-1 rounded-md w-fit' : 'text-slate-600'}`}>
                      {product.stock} {product.unit}
                      {product.stock < lowStockThreshold && <AlertCircle size={16} />}
                    </div>
                  </td>
                  <td className="p-4 text-right">
                    <div className="flex justify-end gap-2 opacity-0 group-hover:opacity-100 transition-opacity">
                      <button 
                        onClick={() => setEditingProduct({...product})}
                        className="text-slate-500 hover:text-amber-600 hover:bg-amber-50 p-2 rounded-lg transition-all"
                        title="Düzəliş et"
                      >
                        <Edit size={18} />
                      </button>
                      <button 
                        onClick={() => onDeleteProduct(product.id)}
                        className="text-slate-500 hover:text-red-600 hover:bg-red-50 p-2 rounded-lg transition-all"
                        title="Sil"
                      >
                        <Trash2 size={18} />
                      </button>
                    </div>
                  </td>
                </tr>
              ))}
              {sortedProducts.length === 0 && (
                <tr>
                  <td colSpan={6} className="p-12 text-center text-slate-400">
                    Məhsul tapılmadı.
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
};

export default Inventory;

export enum Category {
  CEMENT = 'Sement və Qarışıqlar',
  BRICK = 'Kərpic və Blok',
  PAINT = 'Boya və Lak',
  TOOLS = 'Alətlər',
  PLUMBING = 'Santexnika',
  ELECTRIC = 'Elektrik',
  OTHER = 'Digər'
}

export interface Product {
  id: string;
  name: string;
  category: Category;
  price: number;
  cost: number; // Maya dəyəri
  stock: number;
  unit: string; // ədəd, kq, metr, və s.
  imageUrl?: string;
}

export interface CartItem extends Product {
  quantity: number;
}

export interface Sale {
  id: string;
  date: string; // ISO string
  items: CartItem[];
  total: number;
  profit: number;
}

export interface DashboardStats {
  totalRevenue: number;
  totalProfit: number;
  lowStockCount: number;
  totalSalesCount: number;
}

export enum AuditAction {
  ADD = 'ADD',
  DELETE = 'DELETE',
  UPDATE = 'UPDATE',
  SALE = 'SALE',
  BULK_IMPORT = 'BULK_IMPORT'
}

export interface AuditLogEntry {
  id: string;
  date: string;
  action: AuditAction;
  details: string;
}

import React, { useState, useRef } from 'react';
import { Product, Category } from '../types';
import { Plus, Search, Trash2, AlertCircle, ArrowUpDown, ArrowUp, ArrowDown, X, Save, Upload, Download, FileSpreadsheet, Edit, MoreHorizontal, Package, Image as ImageIcon } from 'lucide-react';

interface InventoryProps {
  products: Product[];
  onAddProduct: (p: Product) => void;
  onDeleteProduct: (id: string) => void;
  onUpdateProduct: (p: Product) => void;
  onBulkAddProducts: (products: Product[]) => void;
  lowStockThreshold: number;
}

const Inventory: React.FC<InventoryProps> = ({ products, onAddProduct, onDeleteProduct, onUpdateProduct, lowStockThreshold, onBulkAddProducts }) => {
  const [showForm, setShowForm] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Edit State
  const [editingProduct, setEditingProduct] = useState<Product | null>(null);

  // Sorting & Filtering State
  const [sortConfig, setSortConfig] = useState<{ key: keyof Product; direction: 'asc' | 'desc' } | null>(null);
  const [filterCategory, setFilterCategory] = useState<string>('ALL');
  const [filterStock, setFilterStock] = useState<'ALL' | 'LOW'>('ALL');

  // New Product State
  const [newProduct, setNewProduct] = useState<Partial<Product>>({
    name: '',
    category: Category.OTHER,
    price: 0,
    cost: 0,
    stock: 0,
    unit: 'ədəd',
    imageUrl: ''
  });

  const handleSave = () => {
    if (!newProduct.name || !newProduct.price) return;

    const product: Product = {
      id: Date.now().toString(),
      name: newProduct.name,
      category: newProduct.category as Category,
      price: Number(newProduct.price),
      cost: Number(newProduct.cost),
      stock: Number(newProduct.stock),
      unit: newProduct.unit || 'ədəd',
      imageUrl: newProduct.imageUrl
    };

    onAddProduct(product);
    setShowForm(false);
    setNewProduct({ name: '', category: Category.OTHER, price: 0, cost: 0, stock: 0, unit: 'ədəd', imageUrl: '' });
  };

  const handleUpdateSave = () => {
    if (!editingProduct || !editingProduct.name || editingProduct.price < 0) return;
    onUpdateProduct(editingProduct);
    setEditingProduct(null);
  };

  const handleDownloadTemplate = () => {
    const headers = "name,category,price,cost,stock,unit,imageUrl";
    // Using simple CSV generation. Be wary of commas in data.
    const sample = "Yeni Məhsul,Digər,10.00,8.00,50,ədəd,";
    const csvContent = "data:text/csv;charset=utf-8," + headers + "\n" + sample;
    const encodedUri = encodeURI(csvContent);
    const link = document.createElement("a");
    link.setAttribute("href", encodedUri);
    link.setAttribute("download", "mehsul_sablonu.csv");
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const handleFileUpload = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (e) => {
      const text = e.target?.result as string;
      if (!text) return;

      const lines = text.split('\n');
      const parsedProducts: Product[] = [];

      // Start from index 1 to skip header
      for (let i = 1; i < lines.length; i++) {
          const line = lines[i].trim();
          if (!line) continue;

          // Simple CSV split
          const parts = line.split(',');
          // Handle potential issues if description has commas (not supported in this simple version)
          if (parts.length < 6) continue;

          const [name, category, price, cost, stock, unit, imageUrl] = parts;

          // Basic validation
          if (name && !isNaN(Number(price))) {
              const matchedCategory = Object.values(Category).find(c => c === category.trim()) || Category.OTHER;

              parsedProducts.push({
                  id: Date.now().toString() + Math.random().toString().slice(2, 6) + i,
                  name: name.trim(),
                  category: matchedCategory as Category,
                  price: Number(price),
                  cost: Number(cost) || 0,
                  stock: Number(stock) || 0,
                  unit: unit?.trim() || 'ədəd',
                  imageUrl: imageUrl?.trim() || ''
              });
          }
      }

      if (parsedProducts.length > 0) {
          onBulkAddProducts(parsedProducts);
          if (fileInputRef.current) fileInputRef.current.value = '';
          alert(`${parsedProducts.length} məhsul uğurla idxal edildi!`);
      } else {
          alert('Fayldan heç bir məhsul oxuna bilmədi. Zəhmət olmasa şablonu yoxlayın.');
      }
    };
    reader.readAsText(file);
  };

  const handleSort = (key: keyof Product) => {
    let direction: 'asc' | 'desc' = 'asc';
    if (sortConfig && sortConfig.key === key && sortConfig.direction === 'asc') {
      direction = 'desc';
    }
    setSortConfig({ key, direction });
  };

  const getSortIcon = (columnKey: keyof Product) => {
    if (sortConfig?.key !== columnKey) return <ArrowUpDown size={14} className="text-slate-300" />;
    return sortConfig.direction === 'asc' ? 
      <ArrowUp size={14} className="text-blue-600" /> : 
      <ArrowDown size={14} className="text-blue-600" />;
  };

  // Filter Logic
  const filteredProducts = products.filter(p => {
    const matchesSearch = p.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
                          p.category.toLowerCase().includes(searchTerm.toLowerCase());
    const matchesCategory = filterCategory === 'ALL' || p.category === filterCategory;
    const matchesStock = filterStock === 'ALL' || (filterStock === 'LOW' && p.stock < lowStockThreshold);

    return matchesSearch && matchesCategory && matchesStock;
  });

  // Sort Logic
  const sortedProducts = [...filteredProducts].sort((a, b) => {
    if (!sortConfig) return 0;
    const { key, direction } = sortConfig;

    if (key === 'name' || key === 'category') {
       const valA = a[key].toLowerCase();
       const valB = b[key].toLowerCase();
       if (valA < valB) return direction === 'asc' ? -1 : 1;
       if (valA > valB) return direction === 'asc' ? 1 : -1;
       return 0;
    }

    // Numeric sort
    const valA = Number(a[key as keyof Product]);
    const valB = Number(b[key as keyof Product]);
    return direction === 'asc' ? valA - valB : valB - valA;
  });

  // Mobile Product Card Component
  const MobileProductCard = ({ product }: { product: Product }) => (
    <div className="bg-white p-4 rounded-xl border border-slate-200 shadow-sm space-y-3">
      <div className="flex gap-3">
         {product.imageUrl && (
            <div className="w-20 h-20 shrink-0 rounded-lg border border-slate-100 overflow-hidden bg-slate-50">
               <img src={product.imageUrl} alt={product.name} className="w-full h-full object-cover" />
            </div>
         )}
         <div className="flex-1 min-w-0">
            <div className="flex justify-between items-start">
                <div>
                  <h3 className="font-bold text-slate-800 text-lg truncate">{product.name}</h3>
                  <span className="inline-block mt-1 px-2 py-0.5 bg-slate-100 text-slate-600 text-xs rounded-full">
                    {product.category}
                  </span>
                </div>
                <div className="text-right shrink-0 ml-2">
                   <div className="font-bold text-emerald-600 text-lg">{product.price.toFixed(2)} ₼</div>
                   <div className="text-xs text-slate-400">Maya: {product.cost.toFixed(2)} ₼</div>
                </div>
            </div>
         </div>
      </div>

      <div className="flex justify-between items-center pt-2 border-t border-slate-50">
        <div className={`flex items-center gap-1.5 font-medium ${product.stock < lowStockThreshold ? 'text-amber-600' : 'text-slate-600'}`}>
          <Package size={16} />
          {product.stock} {product.unit}
          {product.stock < lowStockThreshold && <AlertCircle size={16} className="text-amber-500" />}
        </div>

        <div className="flex gap-2">
          <button 
            onClick={() => setEditingProduct({...product})}
            className="p-2 bg-slate-100 text-slate-600 rounded-lg hover:bg-slate-200 active:bg-slate-300 transition-colors"
          >
            <Edit size={18} />
          </button>
          <button 
            onClick={() => onDeleteProduct(product.id)}
            className="p-2 bg-red-50 text-red-500 rounded-lg hover:bg-red-100 active:bg-red-200 transition-colors"
          >
            <Trash2 size={18} />
          </button>
        </div>
      </div>
    </div>
  );

  // Common Form Fields
  const ProductFormFields = ({ prod, setProd }: { prod: any, setProd: any }) => (
    <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-6 gap-4">
      <div className="xl:col-span-6">
        <label className="block text-sm font-medium text-slate-700 mb-1">Şəkil URL</label>
        <div className="flex gap-3 items-center">
            <div className="relative flex-1">
                <ImageIcon className="absolute left-3 top-1/2 transform -translate-y-1/2 text-slate-400" size={18} />
                <input 
                    type="text" 
                    className="w-full border border-slate-300 pl-10 pr-3 py-3 rounded-lg focus:ring-2 focus:ring-blue-500 outline-none transition-all"
                    placeholder="https://example.com/image.jpg"
                    value={prod.imageUrl || ''}
                    onChange={e => setProd({...prod, imageUrl: e.target.value})}
                />
            </div>
            {prod.imageUrl && (
                <div className="w-12 h-12 rounded-lg border border-slate-200 overflow-hidden bg-slate-50 shrink-0 shadow-sm group relative">
                    <img 
                        src={prod.imageUrl} 
                        alt="Preview" 
                        className="w-full h-full object-cover" 
                        onError={(e) => (e.currentTarget.style.display = 'none')} 
                    />
                </div>
            )}
        </div>
      </div>

      <div className="xl:col-span-2">
        <label className="block text-sm font-medium text-slate-700 mb-1">Məhsul Adı</label>
        <input 
          type="text" 
          className="w-full border border-slate-300 p-3 rounded-lg focus:ring-2 focus:ring-blue-500 outline-none transition-all"
          placeholder="Məs: Sement 50kq"
          value={prod.name}
          onChange={e => setProd({...prod, name: e.target.value})}
        />
      </div>
      <div className="xl:col-span-1">
        <label className="block text-sm font-medium text-slate-700 mb-1">Kateqoriya</label>
        <select 
          className="w-full border border-slate-300 p-3 rounded-lg outline-none focus:ring-2 focus:ring-blue-500 bg-white"
          value={prod.category}
          onChange={e => setProd({...prod, category: e.target.value as Category})}
        >
          {Object.values(Category).map(c => <option key={c} value={c}>{c}</option>)}
        </select>
      </div>
      <div>
        <label className="block text-sm font-medium text-slate-700 mb-1">Vahid</label>
        <input 
          type="text" 
          placeholder="ədəd..."
          className="w-full border border-slate-300 p-3 rounded-lg outline-none focus:ring-2 focus:ring-blue-500"
          value={prod.unit}
          onChange={e => setProd({...prod, unit: e.target.value})}
        />
      </div>
      <div>
        <label className="block text-sm font-medium text-slate-700 mb-1">Maya (₼)</label>
        <input 
          type="number" 
          min="0"
          step="0.01"
          className="w-full border border-slate-300 p-3 rounded-lg outline-none focus:ring-2 focus:ring-blue-500"
          value={prod.cost}
          onChange={e => setProd({...prod, cost: Number(e.target.value)})}
        />
      </div>
      <div>
        <label className="block text-sm font-medium text-slate-700 mb-1">Satış (₼)</label>
        <input 
          type="number" 
          min="0"
          step="0.01"
          className="w-full border border-slate-300 p-3 rounded-lg outline-none focus:ring-2 focus:ring-blue-500"
          value={prod.price}
          onChange={e => setProd({...prod, price: Number(e.target.value)})}
        />
      </div>
      <div>
        <label className="block text-sm font-medium text-slate-700 mb-1">Say</label>
        <input 
          type="number" 
          min="0"
          className="w-full border border-slate-300 p-3 rounded-lg outline-none focus:ring-2 focus:ring-blue-500"
          value={prod.stock}
          onChange={e => setProd({...prod, stock: Number(e.target.value)})}
        />
      </div>
    </div>
  );

  return (
    <div className="space-y-6 animate-fade-in pb-20 md:pb-0">
      {/* Hidden File Input */}
      <input 
        type="file" 
        ref={fileInputRef} 
        onChange={handleFileUpload} 
        className="hidden" 
        accept=".csv" 
      />

      {/* Controls Header */}
      <div className="bg-white p-4 rounded-xl shadow-sm border border-slate-100 flex flex-col xl:flex-row gap-4">

        {/* Search */}
        <div className="relative w-full xl:w-96">
          <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 text-slate-400" size={20} />
          <input 
            type="text" 
            placeholder="Məhsul axtar..." 
            className="w-full pl-10 pr-4 py-2.5 border border-slate-200 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500 transition-shadow"
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
          />
        </div>

        {/* Filters - Scrollable Row on Mobile */}
        <div className="flex flex-1 gap-3 overflow-x-auto pb-1 xl:pb-0 no-scrollbar items-center">
          <select 
            className="border border-slate-200 rounded-lg px-3 py-2.5 text-slate-700 bg-white focus:outline-none focus:ring-2 focus:ring-blue-500 min-w-[160px]"
            value={filterCategory}
            onChange={(e) => setFilterCategory(e.target.value)}
          >
            <option value="ALL">Bütün Kateqoriyalar</option>
            {Object.values(Category).map(c => <option key={c} value={c}>{c}</option>)}
          </select>

          <button 
            onClick={() => setFilterStock(filterStock === 'ALL' ? 'LOW' : 'ALL')}
            className={`flex items-center gap-2 px-4 py-2.5 rounded-lg border whitespace-nowrap transition-colors ${
              filterStock === 'LOW' 
                ? 'bg-amber-50 border-amber-200 text-amber-700 font-medium' 
                : 'bg-white border-slate-200 text-slate-600 hover:bg-slate-50'
            }`}
          >
            <AlertCircle size={18} className={filterStock === 'LOW' ? 'text-amber-600' : 'text-slate-400'} />
            <span className="hidden sm:inline">{filterStock === 'LOW' ? 'Kritik Say' : 'Stok Vəziyyəti'}</span>
            <span className="sm:hidden">{filterStock === 'LOW' ? 'Kritik' : 'Stok'}</span>
          </button>

          <div className="flex items-center gap-1 border-l pl-3 border-slate-200 ml-auto xl:ml-0">
             <button 
              onClick={handleDownloadTemplate} 
              className="p-2.5 text-slate-500 hover:text-blue-600 hover:bg-blue-50 rounded-lg transition-colors"
              title="Şablonu yüklə"
            >
              <Download size={20} />
            </button>
            <button 
              onClick={() => fileInputRef.current?.click()} 
              className="p-2.5 text-slate-500 hover:text-blue-600 hover:bg-blue-50 rounded-lg transition-colors"
              title="CSV İdxal et"
            >
              <Upload size={20} />
            </button>
          </div>

           <button 
            onClick={() => setShowForm(!showForm)}
            className={`flex items-center gap-2 px-5 py-2.5 rounded-lg transition-colors whitespace-nowrap shadow-sm font-medium ml-2 ${
              showForm ? 'bg-slate-100 text-slate-700' : 'bg-blue-600 hover:bg-blue-700 text-white'
            }`}
          >
            {showForm ? <X size={20} /> : <Plus size={20} />}
            <span className="hidden sm:inline">{showForm ? 'Bağla' : 'Yeni Məhsul'}</span>
            <span className="sm:hidden">{showForm ? 'Bağla' : 'Yeni'}</span>
          </button>
        </div>
      </div>

      {/* Inline Add Product Form - Desktop/Tablet */}
      {showForm && (
        <div className="bg-white rounded-xl shadow-md border border-blue-100 p-6 animate-fade-in-down">
          <h3 className="text-lg font-bold text-slate-800 mb-5 flex items-center gap-2 border-b border-slate-100 pb-2">
            <Plus className="text-blue-600" size={20} /> Yeni Məhsul Məlumatları
          </h3>
          <ProductFormFields prod={newProduct} setProd={setNewProduct} />
          <div className="flex justify-end gap-3 mt-6">
            <button 
              onClick={() => setShowForm(false)}
              className="px-6 py-2.5 rounded-lg border border-slate-200 text-slate-600 hover:bg-slate-50 font-medium transition-colors"
            >
              Ləğv et
            </button>
            <button 
              onClick={handleSave}
              className="px-6 py-2.5 rounded-lg bg-emerald-600 hover:bg-emerald-700 text-white font-medium flex items-center gap-2 shadow-sm shadow-emerald-200 transition-all hover:scale-[1.02]"
            >
              <Save size={18} />
              Əlavə et
            </button>
          </div>
        </div>
      )}

      {/* Edit Modal - Responsive (Full screen on mobile) */}
      {editingProduct && (
        <div className="fixed inset-0 bg-black/60 backdrop-blur-sm flex items-center justify-center z-50 md:p-4">
          <div className="bg-white w-full h-full md:h-auto md:rounded-2xl md:max-w-4xl shadow-2xl flex flex-col md:max-h-[90vh] animate-scale-in">
            <div className="bg-white px-6 py-4 border-b border-slate-100 flex justify-between items-center sticky top-0 z-10">
              <h3 className="text-lg font-bold text-slate-800 flex items-center gap-2">
                <Edit size={20} className="text-amber-600"/> Məhsulu Redaktə Et
              </h3>
              <button 
                onClick={() => setEditingProduct(null)} 
                className="text-slate-400 hover:text-slate-600 p-2 rounded-full hover:bg-slate-100 transition-colors"
              >
                <X size={24} />
              </button>
            </div>

            <div className="flex-1 p-6 overflow-y-auto">
               <ProductFormFields prod={editingProduct} setProd={setEditingProduct} />

               {/* Additional Edit-specific UI like quick stock adjust */}
               <div className="mt-8 p-4 bg-amber-50 rounded-xl border border-amber-100">
                  <label className="block text-sm font-bold text-amber-800 mb-2 flex items-center gap-2">
                    <AlertCircle size={18}/> Sürətli Anbar Düzəlişi
                  </label>
                  <div className="flex items-center gap-4">
                    <button 
                      onClick={() => setEditingProduct({...editingProduct, stock: Math.max(0, editingProduct.stock - 1)})}
                      className="w-12 h-12 flex items-center justify-center bg-white border border-amber-200 rounded-lg text-amber-700 hover:bg-amber-100 text-xl font-bold"
                    >
                      -
                    </button>
                    <div className="text-2xl font-bold text-slate-800 w-24 text-center">
                      {editingProduct.stock}
                    </div>
                    <button 
                       onClick={() => setEditingProduct({...editingProduct, stock: editingProduct.stock + 1})}
                       className="w-12 h-12 flex items-center justify-center bg-white border border-amber-200 rounded-lg text-amber-700 hover:bg-amber-100 text-xl font-bold"
                    >
                      +
                    </button>
                  </div>
               </div>
            </div>

            <div className="bg-slate-50 px-6 py-4 border-t border-slate-200 flex justify-end gap-3 sticky bottom-0 z-10">
              <button 
                onClick={() => setEditingProduct(null)}
                className="flex-1 md:flex-none px-6 py-3 md:py-2.5 rounded-xl border border-slate-300 text-slate-700 hover:bg-white font-medium transition-colors"
              >
                Ləğv et
              </button>
              <button 
                onClick={handleUpdateSave}
                className="flex-1 md:flex-none px-6 py-3 md:py-2.5 rounded-xl bg-amber-500 hover:bg-amber-600 text-white font-medium flex justify-center items-center gap-2 shadow-lg shadow-amber-200 transition-all active:scale-95"
              >
                <Save size={18} />
                Yadda Saxla
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Product List - Mobile (Cards) & Desktop (Table) */}

      {/* Mobile Card View */}
      <div className="md:hidden space-y-4">
        {sortedProducts.map(product => (
          <MobileProductCard key={product.id} product={product} />
        ))}
        {sortedProducts.length === 0 && (
          <div className="text-center py-12 text-slate-400 bg-white rounded-xl border border-slate-100 border-dashed">
            <Package size={48} className="mx-auto mb-2 opacity-20" />
            <p>Məhsul tapılmadı.</p>
          </div>
        )}
      </div>

      {/* Desktop Table View */}
      <div className="hidden md:block bg-white rounded-xl shadow-sm border border-slate-100 overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full text-left border-collapse">
            <thead>
              <tr className="bg-slate-50 text-slate-600 text-sm font-medium border-b border-slate-100 select-none">
                <th className="p-4 cursor-pointer hover:bg-slate-100 transition-colors" onClick={() => handleSort('name')}>
                  <div className="flex items-center gap-2">Məhsul Adı {getSortIcon('name')}</div>
                </th>
                <th className="p-4 cursor-pointer hover:bg-slate-100 transition-colors" onClick={() => handleSort('category')}>
                  <div className="flex items-center gap-2">Kateqoriya {getSortIcon('category')}</div>
                </th>
                <th className="p-4 cursor-pointer hover:bg-slate-100 transition-colors" onClick={() => handleSort('cost')}>
                   <div className="flex items-center gap-2">Alış {getSortIcon('cost')}</div>
                </th>
                <th className="p-4 cursor-pointer hover:bg-slate-100 transition-colors" onClick={() => handleSort('price')}>
                   <div className="flex items-center gap-2">Satış {getSortIcon('price')}</div>
                </th>
                <th className="p-4 cursor-pointer hover:bg-slate-100 transition-colors" onClick={() => handleSort('stock')}>
                   <div className="flex items-center gap-2">Anbar {getSortIcon('stock')}</div>
                </th>
                <th className="p-4 text-right">Əməliyyatlar</th>
              </tr>
            </thead>
            <tbody>
              {sortedProducts.map(product => (
                <tr key={product.id} className="border-b border-slate-50 hover:bg-slate-50 transition-colors group">
                  <td className="p-4 font-medium text-slate-800">
                    <div className="flex items-center gap-3">
                        {product.imageUrl && (
                            <img src={product.imageUrl} alt="" className="w-10 h-10 rounded-lg object-cover border border-slate-200 bg-slate-50" />
                        )}
                        <span>{product.name}</span>
                    </div>
                  </td>
                  <td className="p-4">
                    <span className="px-2.5 py-1 bg-slate-100 text-slate-600 text-xs rounded-full whitespace-nowrap border border-slate-200">
                      {product.category}
                    </span>
                  </td>
                  <td className="p-4 text-slate-500 font-mono text-sm">{product.cost.toFixed(2)} ₼</td>
                  <td className="p-4 font-bold text-emerald-600 font-mono text-sm">{product.price.toFixed(2)} ₼</td>
                  <td className="p-4">
                    <div className={`flex items-center gap-2 ${product.stock < lowStockThreshold ? 'text-amber-600 font-bold bg-amber-50 px-2 py-1 rounded-md w-fit' : 'text-slate-600'}`}>
                      {product.stock} {product.unit}
                      {product.stock < lowStockThreshold && <AlertCircle size={16} />}
                    </div>
                  </td>
                  <td className="p-4 text-right">
                    <div className="flex justify-end gap-2 opacity-0 group-hover:opacity-100 transition-opacity">
                      <button 
                        onClick={() => setEditingProduct({...product})}
                        className="text-slate-500 hover:text-amber-600 hover:bg-amber-50 p-2 rounded-lg transition-all"
                        title="Düzəliş et"
                      >
                        <Edit size={18} />
                      </button>
                      <button 
                        onClick={() => onDeleteProduct(product.id)}
                        className="text-slate-500 hover:text-red-600 hover:bg-red-50 p-2 rounded-lg transition-all"
                        title="Sil"
                      >
                        <Trash2 size={18} />
                      </button>
                    </div>
                  </td>
                </tr>
              ))}
              {sortedProducts.length === 0 && (
                <tr>
                  <td colSpan={6} className="p-12 text-center text-slate-400">
                    Məhsul tapılmadı.
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
};

export default Inventory;
